  /* =========================================================
     Self-hosted fonts (latin subset). font-display: swap, NOT optional:
     optional gives each face a ~100ms deadline and, if it misses, pins
     the fallback for the whole page life with no second chance. On this
     design the hand and the typewriter ARE the identity, so a face that
     arrives late must still arrive. Preload + the service worker's
     cache-first font branch mean the file is almost always there before
     first paint, so the swap is rarely visible in practice.
     Kept local (not Google Fonts) for no runtime network hop and full
     offline/PWA support. Caveat is variable: one file covers 400-700.
     ========================================================= */

  @font-face {
    font-family: "Caveat";
    font-style: normal;
    font-weight: 400 700;
    font-display: swap;
    src: url("fonts/caveat-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }
  @font-face {
    font-family: "Courier Prime";
    font-style: normal;
    font-weight: 400;
    font-display: swap;
    src: url("fonts/courierprime-400-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }
  @font-face {
    font-family: "Courier Prime";
    font-style: normal;
    font-weight: 700;
    font-display: swap;
    src: url("fonts/courierprime-700-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }
  @font-face {
    font-family: "Courier Prime";
    font-style: italic;
    font-weight: 400;
    font-display: swap;
    src: url("fonts/courierprime-italic-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }

  /* The Stats nemesis clipping's two printed faces: a blackletter masthead and a black
     headline serif. Only that one cutting uses them (see .stp-clip). */
  @font-face {
    font-family: "UnifrakturCook";
    font-style: normal;
    font-weight: 700;
    font-display: swap;
    src: url("fonts/unifrakturcook-700-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }
  @font-face {
    font-family: "Playfair Display";
    font-style: normal;
    font-weight: 900;
    font-display: swap;
    src: url("fonts/playfairdisplay-900-latin.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
  }

  /* =========================================================
     THE SONGWRITER'S NOTEBOOK — core feel (Phases 0–3)
     ========================================================= */

  :root {
    --paper: #f5efe1;
    --paper-edge: #efe7d4;
    --desk: #c8bca6;
    --ink: #2b2722;            /* graphite body ink */
    /* The third face, and the only one that is not stationery: text on a SCREEN, used by
       nothing but the tumblr message cards. Those cards are screenshots pasted into the
       notebook, and a screenshot set in Caveat or Courier Prime would be a drawing of a post
       rather than a picture of one. No file to load — a screenshot wears whatever the phone
       had. Do not reach for this anywhere else; the rule is still hand for creative text and
       typewriter for functional UI. */
    --screen: ui-sans-serif, -apple-system, "Helvetica Neue", Helvetica, Arial, sans-serif;
    --ink-soft: #6f675a;       /* faded pencil */
    --rule: rgba(43, 39, 34, 0.07);   /* ruled lines */
    --margin: rgba(178, 58, 58, 0.45); /* red margin rule: a printed line, meant to sit UNDER text */
    --red-pen: #a8322e;                /* the editor's red pen: solid ink, for text you must be able to read */
    /* --red-pen's opposite number: the tick beside something you got right. Named for the
       same reason the red one is — it is INK, for text and marks you must be able to read,
       not a wash. --margin is the printed line and belongs under text, never as text. */
    --green-pen: #2f6340;
    /* The third pencil in the tin. Blue is what the shelf pins a shortlist in, deliberately
       not a difficulty colour, and it was the darkest of the three at 1.54:1 after dark. */
    --blue-pencil: #274560;

    /* The charm collection's five family hues, one per index tab and the heading above it.
       Tokens rather than the hexes they used to be in ACH_FAMILY_COLORS, because that object
       writes them into an inline --fam and an inline custom property cannot be reached by any
       stylesheet rule. See the note there. Every one of the four columns is a full set. */
    --ach-fam-craft:     #b07d2a;
    --ach-fam-shelf:     #3f6b7d;
    --ach-fam-knowledge: #a33a3a;
    --ach-fam-offpage:   #6b5a3f;
    --ach-fam-sealed:    #6f6a60;

    /* The eighteen charm-theme inks, one per ACH_GROUPS theme. Tokens for the reason the note
       on ACH_GROUP_COLORS gives: they are written inline as --bead / --ach-theme / --plate and
       no stylesheet rule can reach an inline custom property. */
    --ach-th-core: #c8951f;
    --ach-th-perfect: #c2622a;
    --ach-th-clock: #55707f;
    --ach-th-misfires: #8a3b2f;
    --ach-th-daily: #3f7d6e;
    --ach-th-infinite: #2f4d7a;
    --ach-th-lyricist: #9b6b9e;
    --ach-th-catalogue: #b23a3a;
    --ach-th-nemesis: #6d3f5c;
    --ach-th-challenges: #2b2722;
    --ach-th-album-focus: #a8577a;
    --ach-th-custom: #4a6b8a;
    --ach-th-guests: #6b5a92;
    --ach-th-bonus: #2f6f6a;
    --ach-th-ruthless: #8c4a34;
    --ach-th-longhaul: #4a6b3f;
    --ach-th-margins: #7d5a3f;
    --ach-th-mastery: #8a6d1f;

    /* The masthead's gold. Deliberately NOT an era token: the drawn title is the
       one fixed mark on the desk, and a logo that repaints itself every ten
       seconds is not a logo. Era ink starts below the header. */
    --brand-gold: #a9791f;

    /* Era tokens (overridden per round by [data-era]) */
    --ink-accent: #a9791f;
    --highlighter: rgba(247, 201, 72, 0.55);
    --bead: #c8951f;
    --page-wash: rgba(212, 160, 23, 0.05);

    /* The lamp on the sheet. Cut to the same shape as the desk's own lighting in
       body::before, because the notebook is lying on that desk under that light and
       was the one object in the picture with none on it: brighter at the head of the
       page, falling into shade at the foot, which is also what gives a long scrolling
       panel a near edge and a far one.

       A token rather than a literal in .card because dark mode cannot reuse the value.
       A warm white that reads as lamplight on cream paper reads as fog on a dark
       sheet, so the highlight there is barely a twentieth and the shade does the work
       instead. Nothing here is texture: it is one gradient, and it never grains. */
    --paper-light: linear-gradient(180deg,
      rgba(255, 251, 238, 0.34) 0%,
      rgba(255, 251, 238, 0) 22%,
      rgba(74, 53, 29, 0) 68%,
      rgba(74, 53, 29, 0.075) 100%);

    --line: 32px;  /* notebook baseline rhythm */
    --hand: "Caveat", "Bradley Hand", "Segoe Script", cursive;
    --type: "Courier Prime", "Courier New", monospace;
    --text-size-adjust: 0px;
    --tension: 0;  /* 0 calm → 1 the bridge; driven by the timer */
  }

  body[data-text-size="small"] { --text-size-adjust: -1px; }
  body[data-text-size="large"] { --text-size-adjust: 2px; }

  /* ---- Era palettes (accent / highlighter / bead / wash) ---- */
  /* The wash never touches the sheet: .card's paper is the same stock in every era, and
     the era rides on the accent, highlighter and bead. The wash only fills small tiles
     sitting on the page (quest charms, the daily stub and the like), so it still keeps to
     the rule it was written under: it may move a tile's HUE, never its VALUE, which is
     why midnight and reputation carry a pale wash and not their own near-black swatch. */
  body[data-era="gold"]     { --ink-accent:#a9791f; --highlighter:rgba(247,201,72,0.55); --bead:#c8951f; --page-wash:rgba(212,160,23,0.05); }
  body[data-era="lavender"] { --ink-accent:#6d5aa6; --highlighter:rgba(186,160,235,0.50); --bead:#8b73c9; --page-wash:rgba(139,115,201,0.05); }
  body[data-era="red"]      { --ink-accent:#9b2226; --highlighter:rgba(225,90,95,0.42);  --bead:#b23a3f; --page-wash:rgba(178,58,63,0.05); }
  body[data-era="denim"]    { --ink-accent:#3f6fa3; --highlighter:rgba(120,170,220,0.45); --bead:#5b87b8; --page-wash:rgba(91,135,184,0.05); }
  body[data-era="graphite"] { --ink-accent:#4a4a4a; --highlighter:rgba(130,130,130,0.40); --bead:#6b6b6b; --page-wash:rgba(90,90,90,0.05); }
  body[data-era="midnight"] { --ink-accent:#2b3a67; --highlighter:rgba(90,110,180,0.42); --bead:#3d4f86; --page-wash:rgba(150,165,210,0.06); }
  body[data-era="debut"]      { --ink-accent:#3f7d54; --highlighter:rgba(120,185,135,0.42); --bead:#5a9e6e; --page-wash:rgba(63,125,84,0.05); }
  body[data-era="reputation"] { --ink-accent:#2c2c2e; --highlighter:rgba(80,80,86,0.42);   --bead:#3a3a3e; --page-wash:rgba(170,172,180,0.07); }
  body[data-era="lover"]      { --ink-accent:#b8487f; --highlighter:rgba(234,150,196,0.46); --bead:#d472a6; --page-wash:rgba(196,100,154,0.05); }
  body[data-era="evermore"]   { --ink-accent:#6b4a2e; --highlighter:rgba(160,120,80,0.42);  --bead:#8a6038; --page-wash:rgba(122,90,56,0.05); }
  /* Guest washes: one per guest shelf catalogue, worn for a whole guest run (GUESTS[].era).
     Kept OUT of ERAS so Taylor's shuffle can never deal one, and drawn from each pass's own
     ink rather than borrowed from her ten, which dressed other artists in her records. */
  body[data-era="guest-olivia-rodrigo"]    { --ink-accent:#6b3fa0; --highlighter:rgba(176,128,226,0.46); --bead:#7a55b0; --page-wash:rgba(122,85,176,0.05); }
  body[data-era="guest-wicked-soundtrack"] { --ink-accent:#1f6a4f; --highlighter:rgba(232,150,186,0.46); --bead:#3c8a5e; --page-wash:rgba(197,121,155,0.05); }
  body[data-era="guest-hannah-montana"]    { --ink-accent:#673c86; --highlighter:rgba(242,200,64,0.52);  --bead:#8a63a2; --page-wash:rgba(226,182,61,0.06); }
  body[data-era="guest-billie-eilish"]     { --ink-accent:#18221c; --highlighter:rgba(182,214,43,0.40);  --bead:#26332b; --page-wash:rgba(137,151,136,0.07); }
  body[data-era="guest-ariana-grande"]     { --ink-accent:#7d4560; --highlighter:rgba(229,170,184,0.48); --bead:#b87a90; --page-wash:rgba(213,162,180,0.06); }
  body[data-era="guest-harry-styles"]      { --ink-accent:#a4534c; --highlighter:rgba(95,185,224,0.36);   --bead:#c07f7a; --page-wash:rgba(192,127,122,0.05); }
  body[data-era="guest-sabrina-carpenter"] { --ink-accent:#a3303f; --highlighter:rgba(214,168,128,0.46); --bead:#6b4632; --page-wash:rgba(184,119,103,0.05); }

  /* ---- Masthead inks (Album Focus reward, body[data-ink]) ----
     ONE token, --mast-ink, worn by every gold mark in the masthead — the gold word, the star
     over the i, the underline swash and the tagline hearts —
     plus the closed cover's title. The rule is that the wordmark is drawn in ONE pen: leaving
     the swash pinned to --brand-gold left a green title sitting inside yellow
     furniture, which read as a half-finished reward rather than a chosen ink. Every one of
     those reads it as `var(--mast-ink, <its own old value>)`, so with no ink chosen the
     attribute is simply absent and they all keep exactly the colour they had. Never give --mast-ink a :root default: the
     surfaces do NOT share one fallback (the masthead falls back to --brand-gold, the cover to
     --ink-accent) and a root default would silently flatten that difference.

     Keyed on [data-ink] rather than body[data-ink] on purpose: the body wears one for the page,
     and the ink tray's swatch chips each wear their own, so one palette paints both and a chip
     can never show a colour the page would not.

     These are NOT the era accents. Five differ from the era their album plays in, each for a
     reason found by eye on the real oak at real size; MAST_INKS in js/config.js carries the
     reasons, and PLAN.md the full palette note. Do not "simplify" them back to --ink-accent.

     Each ink is stated ONCE, as a day/night pair, and --mast-ink is resolved from that pair.
     That is what lets the generated favicon read --mast-ink-day off the body whatever theme
     the page is wearing: its tile is cream paper at midnight too, so it wants the day column
     and must never be handed the night one. */
  /* The house gold, as a paint key. It is NOT an ink and the body never wears it: choosing
     brand gold REMOVES data-ink, which is what lets every masthead surface fall back to the
     colour it already had. But a chip in the tray sits INSIDE a body that may be wearing an
     ink, and --mast-ink inherits, so a chip with no key of its own was painting itself in
     whatever the title currently wore — brand gold's chip went navy behind a navy title and
     told you the house ink was navy. So the chip states the gold outright. Restated here
     rather than pointing at --brand-gold because the day column has to stay the DAY colour
     whatever theme the page is in (see the favicon note above), and --brand-gold is swapped
     by theme on :root. If the gold on line 109/283 moves, move it here too. */
  [data-ink="brand"]        { --mast-ink-day:#a9791f; --mast-ink-night:#e0a83a; }
  [data-ink="debut"]        { --mast-ink-day:#3f7d54; --mast-ink-night:#74c48b; }
  [data-ink="fearless"]     { --mast-ink-day:#d0a021; --mast-ink-night:#f4cf62; }
  [data-ink="speaknow"]     { --mast-ink-day:#6d5aa6; --mast-ink-night:#bca6f0; }
  [data-ink="red"]          { --mast-ink-day:#9b2226; --mast-ink-night:#eb6a66; }
  [data-ink="nineteen89"]   { --mast-ink-day:#3f6fa3; --mast-ink-night:#74abe1; }
  [data-ink="reputation"]   { --mast-ink-day:#2c2c2e; --mast-ink-night:#a9a8b6; }
  [data-ink="lover"]        { --mast-ink-day:#b8487f; --mast-ink-night:#f194c1; }
  [data-ink="folklore"]     { --mast-ink-day:#7e8180; --mast-ink-night:#9aa1a6; }
  [data-ink="evermore"]     { --mast-ink-day:#7e4a1f; --mast-ink-night:#cb9568; }
  [data-ink="midnights"]    { --mast-ink-day:#2b3a67; --mast-ink-night:#8398da; }
  [data-ink="poets"]        { --mast-ink-day:#856c50; --mast-ink-night:#bda284; }
  [data-ink="showgirl"]     { --mast-ink-day:#c2571a; --mast-ink-night:#f0975a; }
  /* The thirteenth ink: all twelve albums beaten, and the title stops being pinned. It points
     at --ink-accent rather than carrying a hex, so the era palettes, the dark palette and the
     high-contrast palettes all reach it already built and it can never drift out of step with
     them. The note on .mast-gold below still stands for the automatic era wash — the wordmark
     does NOT follow the era by default, and this is the unlock that hands that over by hand.

     One rough edge, accepted: the generated favicon reads --mast-ink-day so it can draw a cream
     tile while the page wears night, but --ink-accent has no day/night pair to read, so on a
     dark page the tile takes the era's dark accent. It is watered down to the legibility floor
     either way, and giving the twelve eras a second palette to fix it would cost far more than
     the tab icon being a shade off. */
  [data-ink="shuffle"] { --mast-ink-day: var(--ink-accent); --mast-ink-night: var(--ink-accent); }
  [data-ink] { --mast-ink: var(--mast-ink-day); }

  /* ---- Gold leaf (the perfect tier) ----
     Beating an album buys its ink; PERFECTING it sets a leaf twinkle beside the star above the i.
     One token
     rather than a thirteenth ink: the leaf is the same gold whichever ink it sits on, which is
     what makes it read as a second, rarer honour instead of another colour to choose. Deliberately
     NOT the board tiles' corner gold (#ddb43c / #c9a435): those are flat paper triangles on the
     page and go DOWN at night, while this sits on the oak beside a wordmark that comes up.
     Flat, both halves. There is no gradient on this star and there should not be one. */
  :root { --leaf: #e0b23c; }
  :root[data-theme="dark"] { --leaf: #f2ce62; }

  /* ---- Paper stocks (Mastery reward, body[data-paper]) ----
     Retint the page surface only — the era accents above keep floating on top.
     Defined before the high-contrast block so high contrast cleanly overrides them. */
  body[data-paper="manila"]    { --paper:#e8d9b8; --paper-edge:#e0cfa8; --rule:rgba(74,54,30,0.10);  --margin:rgba(160,62,46,0.45); }
  body[data-paper="parchment"] { --paper:#f1e4c9; --paper-edge:#e9dab9; --rule:rgba(92,70,40,0.11);  --margin:rgba(158,58,46,0.42); }
  body[data-paper="blush"]     { --paper:#f6e4e4; --paper-edge:#efd6d6; --rule:rgba(120,62,72,0.09);  --margin:rgba(184,70,92,0.45); }
  body[data-paper="slate"]     { --paper:#dfe3e8; --paper-edge:#d4d9df; --rule:rgba(40,55,75,0.11);   --margin:rgba(160,62,62,0.42); }
  body[data-paper="sage"] { --paper:#e2e8d8; --paper-edge:#d6ddcb; --rule:rgba(48,66,44,0.11); --margin:rgba(160,62,46,0.42); }

  /* ---- Dark notebook (Phase 1: base tokens; data-theme lives on <html>) ----
     For genuine low-light reading: a warm dark paper with a warm off-white ink,
     not a cold invert. data-paper is dropped in dark mode (see applySettings), so
     these stand in for every earned paper stock. Era accents still float on top;
     their dark tuning is Phase 2. Defined at :root so they beat the era/stock
     overrides on <body> without a specificity fight. */
  :root[data-theme="dark"] {
    --paper: #2a241b;          /* lifted off the desk so the sheet reads as lit, not lost */
    --paper-edge: #362e24;
    --desk: #12100c;
    --ink: #ece5d6;            /* warm paper-white */
    --ink-soft: #9d947f;       /* faded pencil, lifted for a dark page */
    --rule: rgba(236, 229, 214, 0.08);
    --paper-light: linear-gradient(180deg,
      rgba(255, 240, 208, 0.05) 0%,
      rgba(255, 240, 208, 0) 24%,
      rgba(0, 0, 0, 0) 66%,
      rgba(0, 0, 0, 0.17) 100%);
    --margin: rgba(206, 86, 86, 0.5);  /* the red rule still reads as red */
    --red-pen: #df6b64;                /* brightened so editor's ink stays legible */
    --green-pen: #6fbf8b;              /* lifted the same way, so a tick reads on a dark sheet */
    --blue-pencil: #7090af;
    /* Lifted off the day hues rather than re-picked: same hue, enough lightness to clear the
       night sheet. As the day hexes they measured 2.14:1 to 2.64:1 here. */
    --ach-fam-craft:     #d9a94e;
    --ach-fam-shelf:     #7db4cc;
    --ach-fam-knowledge: #e08080;
    --ach-fam-offpage:   #c2ad84;
    --ach-fam-sealed:    #a8a296;
    /* Same eighteen hues, OKLab lightness moved until each clears the night sheet at about
       4.6:1. Not re-picked: a charm keeps its own ink, it just stops being written in the dark. */
    --ach-th-core: #c8951f;
    --ach-th-perfect: #d4733c;
    --ach-th-clock: #7590a0;
    --ach-th-misfires: #cb7567;
    --ach-th-daily: #5a9888;
    --ach-th-infinite: #6d8fc0;
    --ach-th-lyricist: #ad7cb0;
    --ach-th-catalogue: #e26561;
    --ach-th-nemesis: #b17d9c;
    --ach-th-challenges: #908c85;
    --ach-th-album-focus: #c77296;
    --ach-th-custom: #6e90b0;
    --ach-th-guests: #9583bf;
    --ach-th-bonus: #599792;
    --ach-th-ruthless: #c27b63;
    --ach-th-longhaul: #739567;
    --ach-th-margins: #aa8569;
    --ach-th-mastery: #a6893f;
    /* Default (no-era) accent, lifted for the dark page so the masthead gold and
       "Your best" number don't sit muddy. Per-era dark tunings are below. */
    --brand-gold: #e0a83a;
    --ink-accent: #e0a83a;
    --highlighter: rgba(240, 196, 90, 0.32);
    --bead: #e0a83a;
    --page-wash: rgba(224, 168, 58, 0.06);
    /* Hands the browser's OWN widgets to the dark side: the settings sliders, the <select>
       dropdowns, the scrollbars, and the text fields' insertion caret and selection. None of
       those are drawn by this stylesheet, so no amount of dark rules reaches them — the range
       inputs in Gameplay were rendering as full-brightness light-mode tracks on a night page,
       measured at 1.0 luminance, the brightest thing in the settings binder. One line, and it
       has to live here on :root rather than on body: a scrollbar on the scrolling element
       reads it off the root. */
    color-scheme: dark;
  }
  /* ---- Dark era palettes ----
     The light accents were tuned to sit dark on cream; several (reputation,
     graphite, red, evermore) go invisible on a dark page. Each era gets a
     lifted accent/bead readable on --paper, and a highlighter deep enough that
     the light ink still reads on top of it while the mark still glows. Higher
     specificity than body[data-era] so these win without !important. */
  :root[data-theme="dark"] body[data-era="gold"]     { --ink-accent:#e6ad3d; --highlighter:rgba(240,196,90,0.32); --bead:#e6ad3d; --page-wash:rgba(224,168,58,0.06); }
  :root[data-theme="dark"] body[data-era="lavender"] { --ink-accent:#bca6f0; --highlighter:rgba(176,150,230,0.30); --bead:#bca6f0; --page-wash:rgba(160,135,220,0.06); }
  :root[data-theme="dark"] body[data-era="red"]      { --ink-accent:#eb6a66; --highlighter:rgba(224,96,96,0.30);  --bead:#eb6a66; --page-wash:rgba(210,80,80,0.06); }
  :root[data-theme="dark"] body[data-era="denim"]    { --ink-accent:#74abe1; --highlighter:rgba(120,170,220,0.30); --bead:#74abe1; --page-wash:rgba(110,160,215,0.06); }
  :root[data-theme="dark"] body[data-era="graphite"] { --ink-accent:#bcbcbc; --highlighter:rgba(180,180,180,0.26); --bead:#bcbcbc; --page-wash:rgba(170,170,170,0.05); }
  :root[data-theme="dark"] body[data-era="midnight"] { --ink-accent:#8398da; --highlighter:rgba(120,142,215,0.30); --bead:#8398da; --page-wash:rgba(110,132,205,0.06); }
  :root[data-theme="dark"] body[data-era="debut"]      { --ink-accent:#74c48b; --highlighter:rgba(120,190,140,0.30); --bead:#74c48b; --page-wash:rgba(110,180,130,0.06); }
  :root[data-theme="dark"] body[data-era="reputation"] { --ink-accent:#cdccd2; --highlighter:rgba(150,150,160,0.26); --bead:#cdccd2; --page-wash:rgba(150,150,160,0.06); }
  :root[data-theme="dark"] body[data-era="lover"]      { --ink-accent:#f194c1; --highlighter:rgba(235,150,196,0.30); --bead:#f194c1; --page-wash:rgba(225,140,186,0.06); }
  :root[data-theme="dark"] body[data-era="evermore"]   { --ink-accent:#cb9568; --highlighter:rgba(190,140,90,0.30);  --bead:#cb9568; --page-wash:rgba(180,130,80,0.06); }
  :root[data-theme="dark"] body[data-era="guest-olivia-rodrigo"]    { --ink-accent:#c39cf2; --highlighter:rgba(170,125,228,0.30); --bead:#c39cf2; --page-wash:rgba(160,120,220,0.06); }
  :root[data-theme="dark"] body[data-era="guest-wicked-soundtrack"] { --ink-accent:#6fcf9a; --highlighter:rgba(225,140,180,0.30); --bead:#6fcf9a; --page-wash:rgba(197,121,155,0.06); }
  :root[data-theme="dark"] body[data-era="guest-hannah-montana"]    { --ink-accent:#cfa6ec; --highlighter:rgba(232,190,70,0.30);  --bead:#cfa6ec; --page-wash:rgba(226,182,61,0.06); }
  :root[data-theme="dark"] body[data-era="guest-billie-eilish"]     { --ink-accent:#b9c7b9; --highlighter:rgba(170,205,50,0.24);  --bead:#b9c7b9; --page-wash:rgba(150,165,150,0.06); }
  :root[data-theme="dark"] body[data-era="guest-ariana-grande"]     { --ink-accent:#e6aec2; --highlighter:rgba(225,160,180,0.28); --bead:#e6aec2; --page-wash:rgba(213,162,180,0.06); }
  :root[data-theme="dark"] body[data-era="guest-harry-styles"]      { --ink-accent:#ec9a90; --highlighter:rgba(95,185,224,0.26);   --bead:#ec9a90; --page-wash:rgba(192,127,122,0.06); }
  :root[data-theme="dark"] body[data-era="guest-sabrina-carpenter"] { --ink-accent:#f08a94; --highlighter:rgba(205,160,120,0.28); --bead:#d9a27f; --page-wash:rgba(184,119,103,0.06); }

  /* Masthead inks on the night desk: the night half of each pair above, switched on here. The
     night column is NOT a lightened copy of the day one and is not derivable from it: at night
     the wordmark's other words are a warm cream, so the three monochrome inks (reputation,
     folklore, poets) invert to nearly that same cream and "Song" stops reading as a separate
     word at all. Those three are darkened and tinted by hand. reputation's silver and
     folklore's grey are the tightest pair in the set, held apart only by hue — reputation leans
     violet, folklore leans green — so re-check that pair first if anything here moves. */
  :root[data-theme="dark"] [data-ink] { --mast-ink: var(--mast-ink-night); }
  /* The desk goes to night: a heavy dark wash over the same oak SVG (so the grain
     survives, just dimmed) plus a warm pool of lamplight over where the notebook
     sits — the "lamp on the desk" read, kept even though the paper itself is dark. */
  :root[data-theme="dark"] body { background-color: #12100c; }
  :root[data-theme="dark"] body::before {
    background:
      radial-gradient(ellipse 66% 52% at 50% 26%, rgba(255, 212, 148, 0.12), rgba(255, 212, 148, 0) 62%),
      linear-gradient(rgba(6, 5, 3, 0.88), rgba(6, 5, 3, 0.93));
  }
  /* The sheet lifts off the night desk on a warm hairline, not the light-mode
     white inset + brown drop shadow (both vanish on dark). The ring does the
     separating; a soft dark cast underneath gives it depth. */
  :root[data-theme="dark"] .card {
    box-shadow:
      0 0 0 1px rgba(236, 229, 214, 0.09),
      0 1px 0 rgba(236, 229, 214, 0.05) inset,
      0 26px 60px rgba(0, 0, 0, 0.62),
      0 4px 14px rgba(0, 0, 0, 0.45);
  }
  /* Masthead sits on the desk, not the paper, so its "carved brown" ink goes
     invisible at night. Repaint the non-gold words as warm paper-white with a
     dark underside; the gold word keeps riding --brand-gold. */
  :root[data-theme="dark"] header.title h1 { color: #ece5d6; }
  :root[data-theme="dark"] .mast-line {
    background:
      linear-gradient(180deg, #fbf4e6, #ece5d6 46%, #cabfa6);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent; color: transparent;
    filter:
      drop-shadow(0 1px 0 rgba(0, 0, 0, 0.45))
      drop-shadow(0 2px 6px rgba(0, 0, 0, 0.5));
  }
  /* On the night desk there is no light to cast an underside, and the accent gold
     is already bright against near-black, so the seating shadow only thickens the
     letter. Take it off and let the gold word sit flat. The star keeps its own
     edge: it is a solid mark rather than a stroke, so the highlight still reads. */
  :root[data-theme="dark"] .mast-gold { filter: none; }
  :root[data-theme="dark"] header.title p { color: #b7a888; }
  /* Keepsake nav cards default to a cream stock; give them a dark card so they
     stop glowing. Title/kicker already read from --ink/--ink-soft; the tinted
     seat is lifted so the icon still has a disc to sit on. */
  :root[data-theme="dark"] .nav-card {
    --card-bg: #2f281f;
    border-color: rgba(236, 229, 214, 0.14);
    box-shadow: 0 2px 7px rgba(0, 0, 0, 0.45);
  }
  :root[data-theme="dark"] .nav-card-seat { background: rgba(var(--tint), 0.24); }
  /* Graphite is the page's own near-black, which is the one tint that lifting cannot save:
     at any alpha it lands on #2f281f as nothing, and the challenges target was left
     floating with no disc under it and its fills gone. At night it turns to the pale side
     of graphite instead, which is what the same pencil looks like on dark paper. */
  :root[data-theme="dark"] .nav-card[data-era-tint="graphite"] { --tint: 176, 168, 152; }
  /* The icons' spot is pre-mixed onto the card. Onto #2f281f, 52% of the tint reads as mud,
     so at night the spot takes most of it. The pen needs nothing: it is --ink, which night
     already turns pale. */
  :root[data-theme="dark"] .nav-ic .spot  { fill: color-mix(in srgb, rgb(var(--tint)) 72%, var(--card-bg)); }
  :root[data-theme="dark"] .nav-card:hover .nav-card-seat,
  :root[data-theme="dark"] .nav-card:focus-visible .nav-card-seat { background: rgba(var(--tint), 0.34); }
  :root[data-theme="dark"] .nav-card:hover,
  :root[data-theme="dark"] .nav-card:focus-visible { box-shadow: 0 5px 12px rgba(0, 0, 0, 0.55); }
  :root[data-theme="dark"] .see-also--row .nav-card-seat {
    border-color: rgba(236, 229, 214, 0.16);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  }
  /* Desk props are physical objects (a cream calendar, a cassette), so they
     keep their own colours — but at night the desk is barely lit, and a fully-lit
     cream pad glows brighter than the notebook and steals the eye. Dim the fixed
     props with brightness (their per-variant drop-shadows are preserved, just
     deepened), so everything reads as lit-but-dim. */
  :root[data-theme="dark"] .desk-item {
    filter: drop-shadow(3px 8px 8px rgba(0, 0, 0, 0.55)) saturate(0.82) brightness(0.6);
  }
  :root[data-theme="dark"] .stamp { filter: brightness(0.82) saturate(0.9); }

  * { box-sizing: border-box; }

  /* Pin the page to one axis. The desk layer (.desk-items) is
     absolute/left:0/right:0 with overflow:hidden, so their clip box is the
     initial containing block: exactly the viewport, never the scrollable area.
     Props are deliberately drawn hanging past that edge, so the moment the page
     can pan sideways by a pixel you slide past the clip and land on bare wood
     where half a prop used to be. Vertically the same thing happens at the top:
     the wood tiles infinitely (repeat-y on the propagated canvas background) but
     the props, the notebook and the fixed lighting overlay all stop at y=0, so an
     upward bounce peels the staging away from the desk.

     overflow-x is clip, NOT hidden: hidden on the root turns html into a scroll
     container on the other axis and breaks sticky positioning and scroll
     anchoring. overscroll-behavior kills the elastic bounce on both axes; on
     mobile it also disables pull-to-refresh, which is wanted here, because an
     accidental pull mid-run currently costs the player the run. Inner scrollers
     set their own overscroll-behavior: contain and are unaffected. Neither
     property stops a pinch-zoom pan, and neither should. */
  html { overflow-x: clip; overscroll-behavior: none; }

  body {
    margin: 0;
    min-height: 100vh;
    font-family: var(--type);
    color: var(--ink);
    /* Blonde oak, as ONE image: the stitched turbulence ground and the
       drawn growth figure above it live in a single 4800-tall tile that
       scrolls 1:1 with the notebook and desk props. It used to be two
       layers, and that was the lag on long pages: with a second image
       under it Chrome stopped keeping the drawn tile and re-ran every
       noise filter for each strip of desk scrolled into view (~85ms a
       frame on the charms page). As one image it is drawn once and kept.
       Never split it back into layers, and never add a second background
       image here. Noise stitches at the tile's edges and drawn details
       stay clear of the horizontal join, so a repeat reads as another gap
       between rings. Lighting stays viewport-fixed in body::before,
       separate from the wood. The tile comes out of
       scripts/art/make_oak.py; edit there, never here. */
    background: url("textures/oak-figure.svg") top center / 1200px auto repeat-y;
    background-color: #cdb389;
    display: flex;
    justify-content: center;
    padding: 20px 18px var(--desk-tail, 24px);
  }
  /* The desk margin under the notebook is a tail, not a constant. On a page that
     genuinely scrolls it is run-off: the last row of a long list needs somewhere to
     end, and 64px is what stops it butting into the window edge. On a page that
     very nearly fits, that same 64px is the ONLY thing you can scroll to, so the
     scrollbar buys you nothing but bare wood and the masthead slides off the top for
     it. So the short tail is the default and the long one is switched back on by
     updateDeskTail (js/app.js) once the notebook overflows the window by enough to
     be worth scrolling on its own. */
  body[data-tail="long"] { --desk-tail: 64px; }
  /* Below 1200px the tile is pinned at 1200px wide (cropped, centred) so the
     grain stays at a believable scale on phones; from 1200px up it tracks the
     viewport width exactly. */
  @media (min-width: 1200px) { body { background-size: 100% auto; } }

  /* Desk lighting, fixed to the viewport: it is the lamp and the camera, not
     the wood, so it must NOT scroll with the tile. Faint top light, a gentle
     bottom shade and an edge vignette (all formerly baked into the desk SVG).
     Painted before .desk-items in tree order, so the props sit above it,
     matching the old layering. */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background:
      linear-gradient(180deg, rgba(255,246,223,0.24), rgba(255,246,223,0) 38%, rgba(74,53,29,0) 62%, rgba(74,53,29,0.10)),
      radial-gradient(ellipse 95% 95% at 50% 36%, rgba(74,53,29,0) 45%, rgba(74,53,29,0.22) 100%);
  }

  .app { width: 100%; max-width: 660px; position: relative; z-index: 1; perspective: 1700px; perspective-origin: 50% 0%; }

  /* ---------- Desk props (decorative, desktop only) ----------
     Quiet, semi-realistic objects on the desk. The big ones straddle the
     screen edges, half off the viewport, so the desk reads as continuing past
     the window; the calendar, pencil and picks sit whole on the wood beside
     the notebook, as if just set down. Hidden on narrow screens where they'd
     crowd the notebook. The container is document-anchored (absolute, one
     viewport tall) rather than fixed, so the props sit on the first screenful
     of desk and scroll away with the wood grain; only the lighting overlay
     stays with the viewport. */
  .desk-items { position: absolute; top: 0; left: 0; right: 0; height: 100vh; z-index: 0; pointer-events: none; display: none; overflow: hidden; }
  /* Player-facing decoration density. Quiet keeps the desk's working story but removes the
     largest edge objects. */
  .desk-items { --text-size-adjust: 0px; }
  body[data-desk-density="quiet"] :is(.di-glasses, .di-mug, .di-cassette, .di-crumple) { display: none; }
  body[data-desk-density="bare"] .desk-items { display: none !important; }
  /* December snowfall: full-viewport decorative canvas, above the notebook but
     below the settings modal (z 200). Shown/hidden + animated by app.js, gated on
     December (active timezone) and motion-allowed. */
  #snowfall { position: fixed; inset: 0; z-index: 50; pointer-events: none; display: none; }
  /* Autumn leaves: the snowfall's seasonal sibling. Same layer, same rules, but gated
     on the Halloween week (28 Oct–3 Nov, active timezone) instead of December. */
  #autumnleaves { position: fixed; inset: 0; z-index: 50; pointer-events: none; display: none; }
  .desk-item {
    position: absolute; opacity: 0.92;
    filter: drop-shadow(3px 7px 6px rgba(46,32,14,0.30)) saturate(0.88);
  }
  .desk-item svg { display: block; width: 100%; height: auto; overflow: visible; }

  /* All props share one real-world scale, taken from the notebook page:
     660px of page = 22cm of paper, so roughly 3px per mm. Folded glasses
     ~14cm, mug ~8cm plus its coaster, pencil ~17cm, cassette 10.2cm,
     a desk calendar pad ~8cm wide, picks 3cm. Sizes below follow from that. */
  /* Composition: things live in loose clusters with real empty desk between
     them, not one prop per slot. Left is the writing side (glasses up top,
     then the desk calendar, mug, and the pencil low). Right is the bracelet station up
     top and a music pile (cassette with picks tossed on it) low; the
     mid-right stretch of wood stays deliberately bare. */
  /* screen-edge props: pinned to a viewport edge, roughly half hanging off */
  /* the glasses carry their own contact shadow inside the drawing, so the
     prop shadow here only has to lift them off the wood */
  .di-glasses { width: 420px; top: 4%;   left: 0; transform: translateX(-54%) rotate(-24deg);
    filter: drop-shadow(4px 9px 7px rgba(46,32,14,0.24)) saturate(0.88); }
  .di-mug     { width: 380px; top: 39%;  left: 0; transform: translateX(-49%) rotate(-14deg);
    filter: drop-shadow(6px 13px 11px rgba(46,32,14,0.28)) saturate(0.88); }
  .di-floss   { width: 370px; top: 5%;   right: 0; transform: translateX(34%) rotate(8deg); }
  /* Less overhang than the other edge props get. The insert is written on, and
     the title is centred on the card, and the title is now a different song
     every day (js/cassette.js), so "far enough on" is no longer a fixed answer.
     The module measures the room it actually has and writes smaller when the
     screen edge, rather than the card, is what's binding; what the overhang
     decides is how often that happens. 24% is where three quarters of her
     titles are written at full size, and it is as far onto the screen as the
     tape can come before the narrowest desk that shows props at all (1120px)
     starts tucking the shell under the notebook. */
  .di-cassette{ width: 320px; top: 54%;  right: 0; transform: translateX(24%) rotate(-16deg); }
  /* on-desk props: anchored to the notebook column (the .app is a fixed 660px
     wide whenever props are visible, so calc(50% +/- 330px) is the paper edge)
     rather than the viewport, keeping their gap to the page constant */
  /* the working desk calendar (js/calendar.js draws the live month): a wire-
     bound pad lying flat beside the page, up between the glasses and the mug
     so the writing tools keep the low corner to themselves */
  .di-calendar {
    width: 250px; top: 36%; left: calc(50% - 490px);
    transform: translate(-50%, -50%) rotate(-4.5deg);
    filter: drop-shadow(5px 9px 8px rgba(46,32,14,0.30)) saturate(0.9);
  }
  .di-pencil {
    width: 520px; top: 69%; left: calc(50% - 412px);
    /* near-vertical, tip pointing down the page; the pencil is drawn at real
       proportions so this only rotates, and the scaleY(-1) flip keeps the
       palest hex facet toward the upper-left light after the rotation */
    transform: translate(-50%, -50%) rotate(100deg) scaleY(-1);
    /* shadow offset pre-rotated (filter applies before transform) so the cast
       shadow still falls down-right on screen like every other prop */
    filter: drop-shadow(6.4px 4.2px 6px rgba(46,32,14,0.30)) saturate(0.88);
  }
  /* The grade printed on the barrel. A manufactured mark, so it speaks the
     desk's printed voice like the calendar pad does, and it is set twice: a
     pale copy a third of a unit higher is the lit top edge of the foil, the
     dark copy under it is the stamp itself. Small on purpose — at desk size
     this is about eight pixels of type on a prop nobody is meant to read. */
  .di-pencil .pc-imprint {
    font-family: var(--type); font-size: calc(7.6px + var(--text-size-adjust));
    font-weight: 700; letter-spacing: 1.5px; fill: #8a6415; opacity: 0.72;
  }
  .di-pencil .pc-imprint-foil { fill: #fbe6ad; opacity: 0.6; }
  .di-calendar .cal-grain { opacity: 0.1; }
  /* the red pen rule under the month title */
  .di-calendar .cal-rule { fill: none; stroke: #b23a3f; stroke-width: 1.3; stroke-linecap: round; opacity: 0.6; }
  /* Printed pad type. The pad is a manufactured object, not something the
     player wrote, so it speaks the desk's printed voice — the same Courier
     Prime as every other label on the page — and leaves the handwriting to the
     graphite and red pen marked over it, which are drawn strokes, not type.
     It used to set Georgia, whose figures are OLD-STYLE: 3 4 5 7 9 hang below
     the baseline, which is handsome in a paragraph and wrong in a date grid,
     where thirty-one numerals are meant to sit on one line. Courier's figures
     are lining and monospaced, so the grid's fixed 26.3 column pitch and the
     numerals inside it finally agree with each other. */
  .di-calendar text {
    font-family: var(--type);
    -webkit-user-select: none;
    user-select: none;
  }
  /* The title is sized by CAP HEIGHT, not by the number: Courier Prime's caps
     are about 0.57em against Georgia's 0.69em, so matching the old 17px on
     paper takes roughly 19. SEPTEMBER, the longest month, then sets the block
     (mark + gap + type) down to a left edge of 34.8, which is where the red
     rule beneath it starts, so the widest month lines up with the rule and no
     other month can reach it. */
  .di-calendar .cal-title { font-weight: 700; font-size: calc(19px + var(--text-size-adjust)); letter-spacing: 1px; fill: #55412a; }
  /* The year is on the red plate, with the weekends: the pad is a two-colour job, and a pale
     grey year read as a third ink with no reason to be there. Same red as a weekend date. */
  .di-calendar .cal-title .cal-year { font-weight: 400; font-size: calc(11.5px + var(--text-size-adjust)); letter-spacing: 1px; fill: #a8563e; }
  .di-calendar .cal-week text { font-weight: 700; font-size: calc(8.5px + var(--text-size-adjust)); letter-spacing: 0.6px; fill: #8a7c62; }
  .di-calendar .cal-days text { font-size: calc(11px + var(--text-size-adjust)); fill: #4a4034; }
  .di-calendar .cal-week text.wknd { fill: #b06a50; }
  .di-calendar .cal-days text.wknd { fill: #a8563e; }
  /* A red-letter day: a marked date printed in its mark's ink, which calendar.js has already
     darkened enough to read as type (typeInk). After .wknd on purpose, so a release on a
     Saturday wears its era rather than the weekend red. The small print's day numbers are
     the same second ink. */
  .di-calendar .cal-days text.rl, .di-calendar .cal-key .rl { fill: var(--rl); font-weight: 700; }
  /* The 13th, a gold-letter day: the figure foil-stamped in the pencil imprint's dark gold
     (calendar.js sets the foil's pale lit edge above it). After .rl, so on 13 December the
     foil wins over the cake's pink. */
  .di-calendar .cal-days text.foil, .di-calendar .cal-key .foil { fill: #9c7417; font-weight: 700; }
  /* The small print at the foot of the sheet: printed, so the pad's Courier, at the size
     fine print is on a real eight-centimetre pad. A grey line at 1x, readable up close. */
  .di-calendar .cal-key text { font-size: calc(5.5px + var(--text-size-adjust)); letter-spacing: 0.1px; fill: #7d715a; }
  /* the writer's marks: graphite strikes through the spent days and a red pen
     loop (main stroke + a lighter echo pass) around today */
  /* no stroke-width or opacity here on purpose: calendar.js varies the pressure of
     every strike per date, and a declaration in this file would win over the
     presentation attribute it sets, flattening twenty-five squares back to one weight */
  .di-calendar .cal-strikes path { fill: none; stroke: #6f675a; stroke-linecap: round; }
  .di-calendar .cal-today path { fill: none; stroke: #b23a3f; stroke-linecap: round; stroke-width: 1.55; opacity: 0.8; }
  .di-calendar .cal-today path.echo { stroke-width: 1.05; opacity: 0.5; }
  /* The cassette insert. Same split of voices as the desk calendar: the card is
     a manufactured thing, so its header and spec line are printed in the desk's
     Courier; the title, the version note and the album line are written on the
     printed rules in the same ballpoint the calendar is marked in. */
  .di-cassette text { text-anchor: middle; }
  .di-cassette .cs-side, .di-cassette .cs-spec { text-anchor: start; }
  .di-cassette .cs-spec { text-anchor: end; }
  .di-cassette .cs-side {
    font-family: var(--type); font-weight: 700; font-size: calc(4.4px + var(--text-size-adjust));
    letter-spacing: 1.1px; fill: #fbf3e4;
  }
  .di-cassette .cs-spec {
    font-family: var(--type); font-size: calc(3.8px + var(--text-size-adjust));
    letter-spacing: 0.8px; fill: #fbf3e4; opacity: 0.72;
  }
  .di-cassette .cs-title {
    font-family: var(--hand); font-weight: 700;
    font-size: calc(var(--cs-title-size, 13px) + var(--text-size-adjust));
    fill: #33406a;
  }
  /* the version note trails the title on the same rule, smaller and unbolded,
     the way it gets squeezed in after the song name has already been written */
  .di-cassette .cs-sub {
    font-weight: 400; font-size: calc(var(--cs-sub-size, 7.4px) + var(--text-size-adjust));
    fill: #3d4a72; opacity: 0.84;
  }
  .di-cassette .cs-note {
    font-family: var(--hand); font-size: calc(var(--cs-note-size, 7.2px) + var(--text-size-adjust));
    fill: #4a4632; opacity: 0.72;
  }
  /* The label is date-seeded after the catalogue and handwriting font arrive.
     Keep its mutable ink out of the first paint, including the temporary titles
     used to measure the card, then reveal the complete fitted label at once. */
  .di-cassette :is(.cs-title, .cs-note) { visibility: hidden; }
  .di-cassette svg.is-dubbed :is(.cs-title, .cs-note) { visibility: visible; }
  /* picks ride the cassette pile: right-edge anchored so the pair stays
     together at any viewport width, drawn after it so they land on top. Low
     enough on the shell to catch only its bottom corner — the card above them
     is written on, and a pick lying across a song title reads as a mistake
     rather than as a pick. */
  .di-picks   { width: 155px; top: 72%; right: 36px; transform: rotate(22deg); }
  /* The gauge stamped into the pearloid pick. Courier, because it is moulded
     into a manufactured object rather than written by hand, and tiny: this is
     the thickness marking, and on a real pick you have to tilt it to the light
     to read it. Two passes make the deboss read as cut INTO the plastic rather
     than printed on it: the shaded cut on top, and half a unit below it the
     lower lip of the groove, which is the only part of it facing the lamp. */
  .di-picks .pk-gauge {
    font-family: var(--type); font-weight: 700; font-size: calc(4.6px + var(--text-size-adjust));
    letter-spacing: 0.4px; text-anchor: middle; fill: #8d8064; opacity: 0.5;
  }
  .di-picks .pk-gauge-lip { fill: #fffdf4; opacity: 0.55; }
  /* spilled alphabet beads: 7mm beads at desk scale (21px), one loose spill
     drifting down-left from the floss station */
  .di-beads-r {
    width: 240px; top: 27%; right: 30px;
    filter: drop-shadow(1.5px 3px 2px rgba(46,32,14,0.32)) saturate(0.92);
  }
  .desk-items .bead-letter {
    font: 700 14px "Courier Prime", monospace;
    fill: #2e2b26; text-anchor: middle; opacity: 0.92;
  }
  /* The letter is cut into the bead and inked, not printed on it, so it gets
     the same two-pass deboss the pick's gauge does: the ink on top, and half a
     unit below it the lower lip of the groove, which is the only part of the
     cut facing the lamp. */
  .desk-items .bead-letter-lip { fill: #fffdf3; opacity: 0.75; }
  /* Crumpled draft: below the music pile, as if flicked off the page. Sized
     off the same 3px/mm scale as everything else — a sheet balled up in one
     hand comes out around 5cm across, not the 4.3cm it used to be — and given
     its own shadow pair rather than the shared one, because a dense little
     ball sitting on wood casts a tight dark contact under itself as well as
     the soft cast shadow every prop gets. */
  .di-crumple {
    width: 152px; top: 80%; left: calc(50% + 361px); transform: rotate(-24deg);
    filter: drop-shadow(4px 7px 6px rgba(46,32,14,0.28))
            drop-shadow(1px 2px 1.5px rgba(46,32,14,0.30)) saturate(0.9);
  }

  /* mug steam - four wisps drifting up, each starting a beat after the last so
     the column never pulses as one object. The keyframes own opacity outright,
     which is why a wisp's weight is set as --wisp rather than as an opacity on
     the path: an attribute there would simply be overwritten every frame.
     `backwards` is load-bearing: without it a delayed wisp sits at the SVG
     default opacity of 1 for its whole delay, so every reload flashes the
     column at full strength and then snaps it out as each animation starts. */
  .desk-steam path { --wisp: 0.55; animation: deskSteam 4.4s ease-in-out infinite backwards; transform-origin: center bottom; }
  .desk-steam path:nth-child(2) { --wisp: 0.4; animation-delay: 1.1s; }
  .desk-steam path:nth-child(3) { --wisp: 0.48; animation-delay: 2.2s; }
  .desk-steam path:nth-child(4) { --wisp: 0.34; animation-delay: 3.3s; }
  @keyframes deskSteam {
    0%   { opacity: 0; transform: translateY(4px) scaleY(0.75); }
    35%  { opacity: var(--wisp); }
    70%  { opacity: calc(var(--wisp) * 0.33); }
    100% { opacity: 0; transform: translateY(-12px) scaleY(1.15); }
  }
  /* ---------- The mug: the tap and ripple (see app.js wireDeskMug) ----------
     The desk layer is pointer-events:none as a whole, so the china turns hit testing back on
     for itself and nothing else. No hover state and no hand cursor: this is furniture you
     happen to be able to fidget with, not a control. */
  .mg-hit { pointer-events: auto; cursor: default; }
  /* ONE TAP ON THE SURFACE (markup and the reasoning in index.html).
     Everything below hangs off .is-rippling on the mug's <svg>, not on one group, because a
     tap moves the wave AND the coffee the wave is crossing, and those are different elements.
     The rings are drawn around their own origin, so the scale is a plain transform on the
     group app.js moved into place. */
  .mg-dimple { opacity: 0; }
  /* The fade runs on stroke-opacity, which leaves plain opacity free to carry how much of the
     wave each of the two strokes is worth. Weight and animation on one property would mean
     giving the trough its own keyframes to fall out of step with the crest. */
  .mg-ring circle { fill: none; stroke-opacity: 0; }
  /* Coffee is nearly black, so a ripple on it is mostly the light it throws back and only a
     little of the shadow behind that. Weighted accordingly: the trough is a hint, the crest
     carries the read. */
  .mg-ring-dark { stroke: #2b1806; }
  .mg-ring-lit  { stroke: #f6e2c0; }
  .mg-ripple .mg-ring, .mg-ripple .mg-dimple { transform-box: view-box; transform-origin: 0 0; }
  /* The press. Fast in, slower out, and gone well before the last wave front leaves: a finger
     lifts off coffee long before the coffee has finished answering. */
  .di-mug svg.is-rippling .mg-dimple { animation: mugDimple 340ms cubic-bezier(0.3, 0, 0.2, 1) 1; }
  @keyframes mugDimple {
    0%   { opacity: 0;    transform: scale(0.2); }
    22%  { opacity: 0.26; transform: scale(1); }
    100% { opacity: 0;    transform: scale(1.55); }
  }
  /* The wave fronts. Each ring leaves a beat after the one before it, and the easing is the
     whole trick: a wave front is quick out of the middle and then gives up, so the curve runs
     out of speed long before the animation runs out of time. The stroke thins as it goes,
     because the same water is being asked to cover a longer circle. */
  .di-mug svg.is-rippling .mg-ring { animation: mugRingSpread 1080ms cubic-bezier(0.12, 0.62, 0.24, 1) 1 backwards; }
  .di-mug svg.is-rippling .mg-ring circle { animation: mugRingFade 1080ms cubic-bezier(0.12, 0.62, 0.24, 1) 1 backwards; }
  .di-mug svg.is-rippling .mg-ring-b, .di-mug svg.is-rippling .mg-ring-b circle { animation-delay: 130ms; }
  .di-mug svg.is-rippling .mg-ring-c, .di-mug svg.is-rippling .mg-ring-c circle { animation-delay: 285ms; }
  @keyframes mugRingSpread {
    0%   { transform: scale(calc(0.32 * var(--rx, 1)), calc(0.32 * var(--ry, 1))); }
    100% { transform: scale(calc(var(--spread, 4.6) * var(--rx, 1)), calc(var(--spread, 4.6) * var(--ry, 1))); }
  }
  /* No two of them are the same circle and none of them is quite a circle. Real coffee is not
     drawn with a compass: a wave front comes off a cup wall and a bubble raft slightly out of
     true, and three identical hoops leaving at even intervals is the thing that makes an
     effect read as an effect. The numbers are small on purpose. */
  .mg-ring-a { --rx: 1.04; --ry: 0.97; --spread: 4.9; }
  .mg-ring-b { --rx: 0.96; --ry: 1.05; --spread: 4.15; }
  .mg-ring-c { --rx: 1.02; --ry: 0.99; --spread: 4.55; }
  /* Two keyframes, one clock: the ring's geometry is on the group and its weight is on the
     strokes, and a scaled group would otherwise fatten the stroke exactly as the wave is
     supposed to be losing it. */
  @keyframes mugRingFade {
    0%   { stroke-opacity: 0; stroke-width: 1.15; }
    12%  { stroke-opacity: 0.78; stroke-width: 0.85; }
    58%  { stroke-opacity: 0.34; stroke-width: 0.38; }
    100% { stroke-opacity: 0; stroke-width: 0.18; }
  }
  .mg-ring-dark { opacity: 0.5; }
  /* The coffee the waves are crossing. One shove away from the tap, one smaller overshoot
     back, then still: the direction comes from app.js as a unit vector, and --amp is how much
     of it each layer takes. The reflection moves most because a reflection is the first thing
     a ripple takes apart, the bubbles next because they ride waves rather than resist them,
     and the crema swirl less because it is half sunk in the brew. */
  .mg-window    { --amp: 1.45; }
  .mg-bubbles   { --amp: 1; }
  .mg-crema     { --amp: 0.62; }
  .di-mug svg.is-rippling .mg-slosh { animation: mugSlosh 900ms cubic-bezier(0.24, 0.8, 0.3, 1) 1; }
  @keyframes mugSlosh {
    0%   { transform: translate(0, 0); }
    20%  { transform: translate(calc(var(--mg-push-x, 0) * var(--amp, 1) * 1px),
                                calc(var(--mg-push-y, 0) * var(--amp, 1) * 1px)); }
    52%  { transform: translate(calc(var(--mg-push-x, 0) * var(--amp, 1) * -0.45px),
                                calc(var(--mg-push-y, 0) * var(--amp, 1) * -0.45px)); }
    78%  { transform: translate(calc(var(--mg-push-x, 0) * var(--amp, 1) * 0.16px),
                                calc(var(--mg-push-y, 0) * var(--amp, 1) * 0.16px)); }
    100% { transform: translate(0, 0); }
  }
  body[data-reduce-motion="on"] .di-mug svg.is-rippling :is(.mg-dimple, .mg-ring, .mg-ring circle, .mg-slosh) { animation: none; }
  /* THE RAFT ITSELF (dealt by app.js seedMugRaft, reasoning there). Each bubble wanders a unit
     or so around the spot it surfaced at, on its own duration and started mid-wander by a
     negative delay, so no two are ever in step and the raft never travels as a sheet. Three
     transforms stack here and none of them fights another: the shove on .mg-bubbles, the
     wander on the bubble, the pop on the skin inside it. */
  .mg-bubble { transform-box: view-box; transform-origin: 0 0;
               animation: mugBubbleDrift var(--bd, 11s) ease-in-out var(--bdd, 0s) infinite; }
  /* Four stops rather than two: a bubble jostled by its neighbours does not travel out and
     back along one line, and a plain ping-pong is legible as one within a few seconds. */
  @keyframes mugBubbleDrift {
    0%, 100% { transform: translate(0, 0); }
    26%      { transform: translate(calc(var(--bx, 0) * 1px), calc(var(--by, 0) * 1px)); }
    52%      { transform: translate(calc(var(--bx, 0) * -0.7px), calc(var(--by, 0) * 0.62px)); }
    78%      { transform: translate(calc(var(--bx, 0) * 0.36px), calc(var(--by, 0) * -0.85px)); }
  }
  /* Where a bubble sits is an attribute, and a tap rewrites it (app.js stirMugRaft), so the
     move is transitioned rather than animated: the raft slides to the arrangement the finger
     just made and stays in it. .is-placing is app.js putting a bubble somewhere with no
     journey in between, a fresh raft or one resurfacing after a pop, which must not slide
     across the cup from wherever the last one died. */
  .mg-bubble-body, .mg-bubble-lit { transition: cx 880ms cubic-bezier(0.24, 0.8, 0.3, 1),
                                                cy 880ms cubic-bezier(0.24, 0.8, 0.3, 1); }
  .mg-bubble.is-placing :is(.mg-bubble-body, .mg-bubble-lit) { transition: none; }
  .mg-bubble-skin { transform-box: fill-box; transform-origin: 50% 50%; }
  /* Going. The film thins, the bubble swells, and then it is simply not there: a bubble does
     not fade politely out, so the opacity is held most of the way and dropped at the end. */
  .mg-bubble.is-popping .mg-bubble-skin { animation: mugBubblePop 300ms ease-out 1 forwards; }
  @keyframes mugBubblePop {
    0%   { transform: scale(1);    opacity: 1; }
    70%  { transform: scale(1.45); opacity: 0.55; }
    100% { transform: scale(1.7);  opacity: 0; }
  }
  /* And coming up somewhere else, at whatever size the brew felt like. */
  .mg-bubble.is-surfacing .mg-bubble-skin { animation: mugBubbleUp 460ms cubic-bezier(0.2, 0.7, 0.3, 1) 1 backwards; }
  @keyframes mugBubbleUp {
    0%   { transform: scale(0.3); opacity: 0; }
    100% { transform: scale(1);   opacity: 1; }
  }
  /* Reduced motion keeps the raft, and keeps it randomised: it is the movement that goes, not
     the coffee. app.js stops popping on the same setting. */
  body[data-reduce-motion="on"] .mg-bubble,
  body[data-reduce-motion="on"] .mg-bubble .mg-bubble-skin { animation: none; }
  body[data-reduce-motion="on"] :is(.mg-bubble-body, .mg-bubble-lit) { transition: none; }

  /* the loose beaded strand trailing off the floss skein sways gently */
  .desk-sway { transform-box: fill-box; transform-origin: 50% 0%; animation: deskSway 5.2s ease-in-out infinite; }
  @keyframes deskSway { 0%,100% { transform: rotate(-2.4deg); } 50% { transform: rotate(2.4deg); } }

  /* Props are life-size against the page, so they need real desk room:
     below 1120px the left cluster would pile onto the mug. */
  @media (min-width: 1120px) { .desk-items { display: block; } }

  /* ---------- Title ---------- */
  /* 20px, not 22: the h1 rides 6px up and the tagline 8px down, so the header
     box is 2px taller than it was. Give those 2px back here and the notebook
     below stays exactly where it was drawn. */
  header.title { text-align: center; margin-bottom: 20px; }
  header.title h1 {
    position: relative;
    display: inline-block;
    /* the whole drawn mark sits a few px higher than its box wants, so the
       tagline below it gets room to breathe without the header growing */
    margin: -6px 0 0;
    font-family: var(--hand);
    font-weight: 700;
    font-size: clamp(22px, 6.4vw, 44px);
    line-height: 1.1;
    white-space: nowrap;
    color: #43301a;  /* a darker take on the settings-gear brown, carved into the desk */
    /* The lift (soft drop-shadow so the ink rests on the wood) lives on the fill
       spans, NOT here. A filter on the h1 shadows the WHOLE title as one image,
       so the dark-brown underside pooled behind the gold "Song" as a smudge in
       its "g" crook. Split onto .mast-line (brown lift) and .mast-gold (gold
       lift) so the gold word never has a brown shadow cast behind it. */
    transform: rotate(-1.4deg);
  }
  /* On a sub-page the masthead is a way back to the notebook. Keep it quiet: the ink
     itself never changes colour (the same restraint the section-heading marks learned),
     it only lifts a hair off the desk the way a card does under the cursor. */
  header.title.is-home h1 { cursor: pointer; transition: transform 0.18s ease; }
  header.title.is-home h1:hover { transform: rotate(-1.4deg) translateY(-1.5px) scale(1.012); }
  header.title.is-home h1:active { transform: rotate(-1.4deg) translateY(0) scale(0.996); }
  @media (prefers-reduced-motion: reduce) {
    header.title.is-home h1, header.title.is-home h1:hover, header.title.is-home h1:active { transition: none; transform: rotate(-1.4deg); }
  }

  /* wet-ink gloss: a sheen at the top of the strokes fading into deeper ink below */
  /* NOTE: these gradients span the full line box, and lowercase glyphs only
     sample the middle-to-lower band of it. Keep that band close to the base
     colour or short letters go muddy; shade only the extremes. */
  .mast-line {
    background:
      linear-gradient(180deg, rgba(255,246,222,0.62), rgba(255,246,222,0.08) 26%, rgba(255,246,222,0) 40%, rgba(24,12,2,0) 78%, rgba(24,12,2,0.3) 97%),
      linear-gradient(#5a3f1e, #5a3f1e);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent; color: transparent;
    /* the ink's lift: a light top edge, a tight dark underside (piped ink), and
       a wide ambient. drop-shadow (not text-shadow) so it doesn't bleed through
       the gradient-clipped glyph fill. Kept gentle so the ink rests on the wood
       without a heavy carved shadow. */
    filter: drop-shadow(0 1px 0 rgba(255,248,232,0.32)) drop-shadow(0 1.5px 1px rgba(50,26,7,0.28)) drop-shadow(0 3px 5px rgba(58,30,8,0.16));
    /* Caveat's last stroke overhangs its advance (the closing "n" of Association), and a
       text-clipped background stops at the span's box, so the overhang was sheared off flat.
       Pad the paint box past it and hand the room straight back so the spacing never moves. */
    padding-right: 0.12em; margin-right: -0.12em;
  }
  /* the one gold word in the title. Pinned to --brand-gold, NOT --ink-accent: the
     era accent owns the page below the header, but the masthead is the wordmark and
     has to look the same in every era (reputation and graphite would drain the
     gold out of it entirely). */
  .mast-gold {
    /* Solid brand-gold fill (the same yellow as the rest of the title's accents),
       NOT a gradient clipped to the text: Caveat's big "g" descender hangs below
       the text-clip box, so any clipped fill leaves its tip unpainted (a brown
       smudge when nested in the brown text, a cut-off tip once isolated). A solid
       colour paints the whole glyph, descender and all. */
    color: var(--mast-ink, var(--brand-gold));
    -webkit-text-fill-color: var(--mast-ink, var(--brand-gold));
    /* ONE tight underside and nothing else. The brown words can carry a light top
       edge, a dark underside and a wide ambient because brown on tan has the
       contrast to survive them; mid-gold on tan does not. Stacking a near-white
       edge above a blurred dark edge below softened the glyph from both sides at
       once, and the word went to mush at a distance. So: no light edge, no wide
       ambient, and the remaining shadow is a half-pixel blur rather than a glow,
       just enough to seat the gold on the wood instead of floating over it. */
    filter: drop-shadow(0 1px 0.5px color-mix(in srgb, var(--mast-ink, var(--brand-gold)), #000 55%));
    /* Safari paints a filtered inline element only inside its own box, and the "g" overhangs
       its advance, so its right side was sheared off flat (Chromium lets the ink spill). Same
       pad-and-hand-back as .mast-line: the paint box grows, the spacing does not move. */
    padding-right: 0.12em; margin-right: -0.12em;
  }
  /* the dot on the first i becomes the game's gold star */
  .mast-i { position: relative; }
  .mast-i .mast-star {
    position: absolute; left: 0.185em; top: 0.44em;  /* measured onto the i stem top */
    width: 0.27em; height: 0.27em;
    transform: translate(-50%, -50%) rotate(-8deg);
    /* wears the same gold as the "Song" letters but keeps its own lifted edge:
       a star is a solid little mark, not a run of thin strokes, so the near-white
       top edge that blurred the word reads as a highlight on it instead. */
    fill: var(--mast-ink, var(--brand-gold));
    stroke: var(--mast-ink, var(--brand-gold)); stroke-width: 1.1;
    stroke-linejoin: round; stroke-linecap: round;
    filter: drop-shadow(0 1px 0 rgba(255,248,232,0.45)) drop-shadow(0 2px 5px rgba(58,30,8,0.28));
  }
  /* Leafed, once the worn ink's album has been PERFECTED. The star itself never changes: it is
     the one mark in the header showing the ink at full strength, and anything laid over it or
     round it dilutes that. A gold rim turned a green or a navy star into a gold-edged star that
     no longer matched the word it sits two letters away from, so the second tier arrives as its
     own mark instead, a small leaf twinkle set off the star's upper point, which reads as the
     star having been gilded without touching a pixel of the ink. Hidden outright until then,
     since an ungilded twinkle in the ink would just be a second star. */
  .mast-i .mast-gild { display: none; }
  body[data-gild="leaf"] .mast-i .mast-gild {
    display: block;
    position: absolute; left: 0.345em; top: 0.315em;
    width: 0.155em; height: 0.155em;
    transform: translate(-50%, -50%) rotate(6deg);
    fill: var(--leaf);
    filter: drop-shadow(0 1px 0 rgba(255,248,232,0.4)) drop-shadow(0 1.5px 3px rgba(58,30,8,0.26));
  }
  /* a songwriter's underline flourish, drawn in the same pen as the era ink: the
     pen comes in low at the left, turns a single leaning loop under the "S",
     then runs the width of the title in three easing swings and lifts off the
     paper past the final "n". Generated by scripts/ui/make_swash.py, which owns
     the amplitude decay and the per-swing wobble; redraw it there rather than
     editing the path by hand. */
  .mast-swash {
    position: absolute; left: 50%; bottom: -0.554em;
    /* the full title width, not an inset: at 90% the loop drifted off the "S"
       and landed under the "w", and the run died under "Associatio" */
    width: 100%; height: auto; overflow: visible;
    transform: translateX(-50%);
    /* BEHIND the words. h1 carries a rotate, so it is already a stacking
       context and a negative index parks the flourish under the ink without
       escaping the title. The letters have to cut through the line where the
       two cross, or the underline reads as pasted over the top. */
    z-index: -1;
    /* the stroke scales with the title (no non-scaling-stroke) so the underline
       keeps its pen weight at every size. 2.35 user units, not the 2.8 the old
       inset rule carried: the wider svg scales user units up with it.
       the drawing space is 320x34 with the wave axis on y=14, and the -0.554em
       drop is what lands that axis on the h1 content bottom, where the old flat
       rule sat. Move one and you must move the other. */
    stroke: var(--mast-ink, var(--brand-gold)); opacity: 0.85; pointer-events: none;
  }
  header.title p {
    /* enough top clearance that the swash's entry loop never strikes it: the
       loop is the lowest ink in the masthead, hanging about 10px clear here */
    margin: 24px 0 0;
    font-family: var(--type);
    font-size: calc(12px + var(--text-size-adjust)); letter-spacing: 1px;
    color: #7a5c38;  /* warm desk-brown, a faded sibling of the title's #4a3518 (sits on wood, not paper) */
  }
  /* Nudged clear of the swash without paying for it in layout: a transform moves
     the ink only, so the notebook below stays exactly where it was drawn. */
  .tagline-row { transform: translateY(5px); }
  /* small inked hearts holding the tagline */
  .tagline-row .tag-heart {
    width: 13px; height: auto; overflow: visible;
    margin: 0 10px; vertical-align: -2px;
    fill: none; stroke: var(--mast-ink, var(--brand-gold));
    stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
    opacity: 0.9;
  }

  /* ---------- Paper page ---------- */
  .card {
    position: relative;
    background:
      /* the lamp, above everything else on the sheet so it falls across the rulings
         and the margin the same way it falls across the paper between them */
      var(--paper-light),
      /* red margin rule as a background layer so it spans the full scroll height
         (the old absolute ::before stopped at the visible box in scrolling cards). */
      linear-gradient(to right, transparent var(--rule-x, 44px), rgba(178, 58, 58, 0.38) var(--rule-x, 44px), rgba(178, 58, 58, 0.38) calc(var(--rule-x, 44px) + 2px), transparent calc(var(--rule-x, 44px) + 2px)),
      repeating-linear-gradient(
        to bottom,
        var(--paper) 0,
        var(--paper) calc(var(--line) - 1px),
        var(--rule) calc(var(--line) - 1px),
        var(--rule) var(--line)
      );
    /* The light has to span the whole sheet however tall it grows, so it is sized to
       the box rather than left on auto. Four entries for four layers, and it has to
       sit after the shorthand, which resets it. */
    background-size: 100% 100%, auto, auto, auto;
    background-color: var(--paper);
    border-radius: 3px;
    padding: 30px 30px 34px 58px;   /* extra left pad for the margin */
    box-shadow:
      0 1px 0 #fff inset,
      0 18px 40px rgba(60, 50, 35, 0.28),
      0 2px 6px rgba(60, 50, 35, 0.18);
    /* deckled / torn-ish edge softness */
    transition: background 0.5s ease;
  }
  /* tension vignette — the room dims as the timer runs out */
  .card::after {
    content: ""; position: absolute; inset: 0; border-radius: 3px;
    pointer-events: none; z-index: 5;
    background: radial-gradient(108% 82% at 50% 43%,
      transparent 36%, rgba(58,14,14,0.5) 76%, rgba(34,6,6,0.82) 100%);
    opacity: var(--tension, 0);
    transition: opacity 0.15s linear;
  }

  /* hurried tally scrawled in the outer margin in the final seconds */
  .margin-tally {
    position: absolute; left: 8px; top: 39%; z-index: 6;
    font-family: var(--hand); font-weight: 700; font-size: calc(42px + var(--text-size-adjust));
    color: var(--margin); opacity: 0; transform: rotate(-9deg);
    pointer-events: none;
  }
  .margin-tally.show { animation: tally 0.95s ease-out; }
  @keyframes tally {
    0%   { opacity: 0; transform: rotate(-9deg) scale(0.6); }
    25%  { opacity: 0.95; transform: rotate(-9deg) scale(1.05); }
    100% { opacity: 0; transform: rotate(-9deg) scale(1.15) translateY(-8px); }
  }

  /* Small pencil strokes in the notebook margin form a quiet page register.
     The irregular lengths and angles keep it handwritten rather than reading as app chrome. */
  .page-register {
    position: absolute; left: 14px; top: 88px; z-index: 6;
    display: none; flex-direction: column; align-items: flex-start; gap: 7px;
    width: 20px; pointer-events: none; user-select: none;
  }
  .page-register.show { display: flex; }
  .page-register-mark {
    display: block; width: var(--register-width, 8px); height: 2px;
    border-radius: 999px; background: var(--ink-soft); opacity: 0.22;
    transform: translateX(var(--register-x, 0)) rotate(var(--register-tilt, 0deg));
    transform-origin: left center;
    transition: width 0.24s ease, background-color 0.24s ease, opacity 0.24s ease;
  }
  .page-register-mark.is-complete { opacity: 0.62; }
  .page-register-mark.is-current {
    width: 14px; height: 3px; background: var(--register-accent, var(--ink-accent)); opacity: 0.95;
    box-shadow: 0 0.5px 0 rgba(43, 39, 34, 0.12);
  }
  body[data-reduce-motion="on"] .page-register-mark { transition: none; }

  /* ---- the streak mark, and the glitter it throws ----------------------------------
     The run's correct-in-a-row count, penciled in the outer margin BELOW the page register
     (which ends at y=199) and below the lives tally (y=190), the two things that already
     live in this gutter. They are mutually exclusive with each other and neither moves, so
     one fixed top clears both.

     The third occupant is the one that cannot be cleared by position: .margin-tally, the red
     3-2-1 countdown, sits at 39% of the card and therefore moves with the card's height. Two
     big hand-drawn numerals in a 44px gutter would be confusing at the best of times, and
     actively bad when the streak happens to read 3 while the clock does. So the streak mark
     stands down for the three seconds the countdown owns the margin, rather than either one
     being nudged around the other. */
  .streak-mark {
    position: absolute; left: 4px; top: 214px; z-index: 6;
    width: 38px; text-align: center;
    font-family: var(--hand); font-weight: 700; font-size: calc(26px + var(--text-size-adjust));
    line-height: 1; color: var(--ink-soft);
    transform: rotate(-4deg); pointer-events: none; user-select: none;
    display: none;
    transition: color 0.18s ease, opacity 0.2s ease;
  }
  .streak-mark.show { display: block; }
  /* the short pencil underline it sits on, struck slightly off-square like the register's own
     marks: the gutter's whole job is to look jotted rather than printed */
  .streak-mark::after {
    content: ""; position: absolute; left: 7px; right: 9px; bottom: -6px; height: 1.5px;
    background: var(--ink-soft); opacity: 0.32; transform: rotate(1.2deg);
  }
  /* the countdown has the margin — see the note above */
  .streak-mark.is-yielding { opacity: 0; }

  /* the numeral kicks as it throws, then settles */
  @keyframes streak-kick {
    0%   { transform: rotate(-4deg) scale(1); }
    28%  { transform: rotate(-7deg) scale(1.32); }
    100% { transform: rotate(-4deg) scale(1); }
  }
  .streak-mark.is-kick { animation: streak-kick 0.42s cubic-bezier(0.2, 0.9, 0.3, 1); }

  /* the miss: the count drops off the page in the editor's red instead of bursting */
  @keyframes streak-drop {
    0%   { transform: rotate(-4deg) translateY(0); opacity: 1; }
    18%  { transform: rotate(-2deg) translateY(-7px); opacity: 1; }
    100% { transform: rotate(16deg) translateY(150px); opacity: 0; }
  }
  .streak-fall {
    position: absolute; left: 4px; width: 38px; text-align: center; z-index: 6;
    font-family: var(--hand); font-weight: 700; font-size: calc(26px + var(--text-size-adjust));
    line-height: 1; color: var(--red-pen); pointer-events: none;
    animation: streak-drop 0.7s cubic-bezier(0.5, 0, 0.85, 0.5) forwards;
  }

  /* Each scrap is two nested elements so the path is an arc rather than a straight line: the
     outer carries the outward throw on an ease-OUT (fast, then slowing), the inner the fall on
     an ease-IN (slow, then accelerating). Multiplying the two gives a parabola for two
     transforms and no per-frame JS, which matters because this fires on every answer. */
  .streak-glitter { position: absolute; inset: 0; pointer-events: none; overflow: visible; z-index: 7; }
  .streak-bit {
    position: absolute; will-change: transform, opacity;
    animation: streak-throw var(--dur) cubic-bezier(0.16, 0.85, 0.36, 1) forwards;
  }
  .streak-bit > span {
    display: block;
    font-family: var(--hand); font-weight: 700; line-height: 1;
    font-size: calc(var(--sz) * 1px); color: var(--tint, var(--ink));
    animation: streak-fall var(--dur) cubic-bezier(0.42, 0, 0.9, 0.72) forwards;
  }
  @keyframes streak-throw {
    0%   { transform: translate(0, 0); opacity: 0; }
    9%   { opacity: 1; }
    72%  { opacity: 1; }
    100% { transform: translate(calc(var(--dx) * 1px), calc(var(--dy) * 1px)); opacity: 0; }
  }
  @keyframes streak-fall {
    0%   { transform: translateY(0) rotate(0deg) scale(0.55); }
    22%  { transform: translateY(0) rotate(calc(var(--rot) * 0.25deg)) scale(1.06); }
    100% { transform: translateY(calc(var(--drop) * 1px)) rotate(calc(var(--rot) * 1deg)) scale(0.92); }
  }

  /* infinite-mode lives: pencil tally strokes scrawled down the outer margin,
     each crossed out as a life is spent */
  .lives-tally {
    position: absolute; left: 10px; top: 90px; z-index: 6;
    display: none; flex-direction: column; gap: 11px;
    pointer-events: none;
  }
  .lives-tally.show { display: flex; }
  .life-mark {
    position: relative; width: 4px; height: 26px; border-radius: 2px;
    background: var(--ink-soft);
    transform: rotate(-8deg); opacity: 0.85;
    transition: opacity 0.3s ease;
  }
  .life-mark.spent { opacity: 0.32; }
  /* the diagonal slash that crosses out a spent life */
  .life-mark.spent::after {
    content: ""; position: absolute; left: -7px; top: 11px;
    width: 20px; height: 2.5px; border-radius: 2px;
    background: var(--margin); transform: rotate(28deg);
    transform-origin: center;
    animation: strike 0.34s ease-out;
  }
  @keyframes strike {
    from { width: 0; opacity: 0; }
    to   { width: 20px; opacity: 1; }
  }

  /* Floating-rarity level gauge (Custom's "Floating" pool): the rarity level you're riding,
     shown as four lit pips with a promo sub-meter filling toward the next. Notebook-honest,
     not an XP bar. */
  .float-gauge {
    display: none; align-items: center; justify-content: center; gap: 10px;
    flex-wrap: wrap; margin: 2px auto 10px; padding: 5px 12px;
    width: max-content; max-width: 90%;
    border: 1.4px solid rgba(43,39,34,0.18); border-radius: 16px;
    background: rgba(247,201,72,0.07);
  }
  .float-gauge.show { display: flex; }
  .adapt-label {
    font-family: var(--type); font-size: calc(11px + var(--text-size-adjust)); letter-spacing: 0.4px;
    text-transform: uppercase; color: var(--ink); font-weight: 700; white-space: nowrap;
  }
  .adapt-pips { display: inline-flex; gap: 5px; }
  .adapt-pip {
    width: 9px; height: 9px; border-radius: 50%;
    border: 1.4px solid var(--ink-soft); background: transparent;
    transition: background 0.3s ease, transform 0.3s ease;
  }
  .adapt-pip.on { background: var(--ink-soft); }
  .adapt-pip.cur { background: var(--ink); border-color: var(--ink); transform: scale(1.35); }
  .adapt-meter {
    position: relative; width: 46px; height: 5px; border-radius: 3px;
    background: rgba(43,39,34,0.14); overflow: hidden;
  }
  .adapt-meter i {
    position: absolute; left: 0; top: 0; height: 100%; border-radius: 3px;
    background: var(--ink); transition: width 0.3s ease;
  }
  .adapt-meter--top { background: var(--highlighter, rgba(247,201,72,0.5)); }
  [data-reduce-motion="on"] .adapt-pip,
  [data-reduce-motion="on"] .adapt-meter i { transition: none; }

  /* Visually hidden but available to screen readers — used for live status/timer
     cues and any text alternative to a purely visual element. */
  .sr-only {
    position: absolute !important;
    width: 1px; height: 1px;
    padding: 0; margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
  /* A focused screen container shouldn't draw a focus ring (focus is moved there
     programmatically for screen-reader/keyboard users, not by tabbing). */
  .screen:focus { outline: none; }
  .screen:focus-visible { outline: none; }

  .screen { display: none; }
  /* the play page paints over the challenge tab tucked behind its fore-edge */
  #screen-game { z-index: 1; }
  .screen.active { display: block; animation: fade 0.4s ease; }
  @keyframes fade { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

  /* The viewport layer keeps transformed sheets out of document layout and catches pointer
     input until the destination is genuinely live. Its perspective origin is aligned to the
     notebook by beginPageTurn, so moving the clone to <body> does not change the hinge. */
  .page-flip-layer {
    position: fixed; inset: 0; z-index: 80; overflow: clip;
    pointer-events: auto; touch-action: none;
    perspective: 1700px;
    perspective-origin: var(--flip-origin-x, 50%) var(--flip-origin-y, 0%);
  }

  /* page turn: the answered page (a cloned sheet) lifts from its top edge and
     flips away toward the reader, revealing the next page already in place beneath */
  .page-flip-sheet {
    display: block; position: absolute; z-index: 1; pointer-events: none;
    transform-origin: top center; backface-visibility: hidden;
    box-shadow: 0 22px 44px rgba(60, 50, 35, 0.34);
    animation: pageFlip 0.5s cubic-bezier(.42,.04,.34,1) forwards;
    will-change: transform;
  }
  .page-flip-sheet .flip-shade {
    position: absolute; inset: 0; border-radius: 3px; pointer-events: none; z-index: 12;
    background: linear-gradient(to top, rgba(38,24,10,0.42), rgba(38,24,10,0.06) 48%, rgba(255,255,255,0.10) 100%);
    opacity: 0; animation: pageFlipShade 0.5s ease-in forwards;
  }
  @keyframes pageFlip {
    from { transform: rotateX(0deg); }
    to   { transform: rotateX(108deg); }
  }
  @keyframes pageFlipShade { from { opacity: 0; } to { opacity: 1; } }

  /* side-to-side page turns for screen navigation, both pivoting on the left spine.
     --side (FORWARD into a sub-page): the leaving page turns away to the left, revealing
     the destination beneath. --in (BACK / give-up): the destination page turns in from the
     left, landing on top of the page being left behind. */
  .page-flip-sheet.page-flip-sheet--side,
  .page-flip-sheet.page-flip-sheet--in {
    transform-origin: center left;
  }
  .page-flip-sheet.page-flip-sheet--side { animation-name: pageFlipSide; }
  .page-flip-sheet.page-flip-sheet--in   { animation-name: pageFlipIn; }
  .flip-shade.flip-shade--side,
  .flip-shade.flip-shade--in {
    background: linear-gradient(to left, rgba(38,24,10,0.42), rgba(38,24,10,0.06) 48%, rgba(255,255,255,0.10) 100%);
  }
  .flip-shade.flip-shade--in { animation-name: pageFlipShadeOut; }
  /* A frozen, non-animating backdrop clone of the page being left, sitting beneath the
     incoming sheet during a back/"in" turn (see flipInToScreen). Its shade is suppressed, and it
     wears the card's own resting shadow rather than the flip sheet's lifted one: the real page
     underneath is hidden for the length of the turn, so this clone is the only thing casting
     onto the desk and should sit as flat as the page it's standing in for. */
  .page-flip-sheet.flip-static {
    animation: none;
    box-shadow: 0 18px 40px rgba(60, 50, 35, 0.28), 0 2px 6px rgba(60, 50, 35, 0.18);
  }
  .flip-shade.flip-shade--off { display: none; }
  @keyframes pageFlipSide {
    from { transform: rotateY(0deg); }
    to   { transform: rotateY(-104deg); }
  }
  @keyframes pageFlipIn {
    from { transform: rotateY(-104deg); }
    to   { transform: rotateY(0deg); }
  }
  @keyframes pageFlipShadeOut { from { opacity: 1; } to { opacity: 0; } }

  /* ---------- Buttons (hand-drawn / taped) ----------
     Registered colour properties so a patterned button's wash AND its ink
     (dots/stripes/grid, drawn as gradients) can fade together on hover. Plain
     background-image gradients can't be interpolated, so without this the
     pattern snaps to its hover colour instantly while the wash fades, flashing
     the button. Driving both through animatable custom properties keeps them
     even. See #backToChallenges / #replayChallenge below. */
  @property --btn-wash { syntax: "<color>"; inherits: false; initial-value: transparent; }
  @property --btn-mark { syntax: "<color>"; inherits: false; initial-value: transparent; }
  button {
    font-family: var(--type); cursor: pointer; border: none;
    transition: background 0.18s, color 0.18s, transform 0.12s, box-shadow 0.2s;
  }
  button:active { transform: translateY(1px) scale(0.99); }

  .btn-primary {
    display: block; width: 100%; margin: 0 auto;
    padding: 14px 18px; font-size: calc(15px + var(--text-size-adjust)); letter-spacing: 1px; font-weight: 700;
    color: var(--ink); background: var(--highlighter);
    border: 2px solid var(--ink);
    border-radius: 2px;
    box-shadow: 3px 3px 0 rgba(43, 39, 34, 0.18);
    transform: rotate(-0.6deg);
  }
  .btn-primary:hover { background: var(--ink); color: var(--paper); }

  /* Start writing: one surface shared with the Mastery swatches and words picker.
     Each finish supplies its art and colours; the label stays above a clipped decorative
     layer. Physical colours keep the material recognisable on either paper theme. */
  .btn-primary.play-cta {
    --cta-fill: #efb73e; --cta-text: #2b2722;
    --cta-hover-fill: var(--cta-fill); --cta-hover-text: #fff0ce;
    position: relative; isolation: isolate; overflow: visible;
    font-size: calc(17px + var(--text-size-adjust));
    background-color: var(--cta-fill); color: var(--cta-text);
    background-image: linear-gradient(168deg, #ffffff57 0%, #ffffff00 46%, #2b27221f 100%), var(--cta-art, none);
    border-color: var(--ink); box-shadow: 3px 3px 0 #2b272238;
    transition: background-color .45s ease, color .3s ease, transform .2s, box-shadow .2s;
  }
  /* The default gold on the night desk. Every other finish is a MATERIAL and keeps its own
     colour on either paper (see above) — but plain gold is not a material, it is the era's
     accent worn as a button, and the era accent already has a night value. So the CTA is taken
     down to meet it rather than given a hand-picked third gold that would drift from the
     masthead and the beads.

     #dba93b is 90% of #efb73e mixed with the ink, which lands on 0.44 luminance, the night
     --brand-gold to within a rounding error, and holds 7.2:1 against the paper.

     It matters because of the size. At #efb73e this is a 31,000px slab at 0.53 luminance on a
     0.02 desk, comfortably the brightest object on the screen and reading as a light source
     rather than as a stroke of marker. The night gold keeps it the brightest thing on the page
     (7.2:1 against the paper, against ink at 6.9:1 on the fill) without the glare. The white
     sheen down the face comes back to a third of its daytime strength for the same reason it
     did on the tape: a highlight only reads as a highlight against a lit surface. */
  :root[data-theme="dark"] .btn-primary.play-cta:not([data-startbtn]) {
    --cta-fill: #dba93b;
    background-image: linear-gradient(168deg, #ffffff1f 0%, #ffffff00 46%, #2b272233 100%), var(--cta-art, none);
  }

  .cta-label { position: relative; z-index: 1; }
  .cta-mark {
    display: inline-block; margin-right: 9px; vertical-align: -3px;
    width: calc(19px + var(--text-size-adjust)); height: calc(19px + var(--text-size-adjust));
  }
  .cta-mark svg { display: block; width: 100%; height: 100%; overflow: visible; }
  .cta-mark--pencil { transform-origin: 70% 90%; }
  .cta-mark .ink-fill { fill: currentColor; stroke: none; }
  .cta-mark .ink { fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; }
  .btn-primary.play-cta::after {
    content: ""; position: absolute; z-index: 1; left: 16%; right: 16%; bottom: 9px; height: 2px;
    background: currentColor; border-radius: 2px; opacity: .7;
    transform: scaleX(0); transform-origin: left center; transition: transform .28s ease;
  }
  .play-cta[data-startbtn="sky"]::after, .play-cta[data-startbtn="meadow"]::after { content: none; }
  .cta-fx { position: absolute; inset: 0; z-index: 0; overflow: hidden; border-radius: inherit; pointer-events: none; }
  .cta-fx * { pointer-events: none; }
  .cta-fx > * { position: absolute; }

  /* The same interaction on a real button or its enclosing picker control. Keep motion
     off the preview's outer box: its transform is also what scales and centres it. */
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) {
    background-color: var(--cta-hover-fill); color: var(--cta-hover-text);
  }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta)::after { transform: scaleX(1); }
  button.play-cta:is(:hover, :focus-visible) { animation: none; transform: rotate(-.6deg) translateY(-2px); box-shadow: 3px 5px 0 #2b272238; }
  button.play-cta:active { transform: rotate(-.6deg) translateY(1px); }
  .play-cta:focus-visible { outline: 2px solid var(--ink); outline-offset: 5px; }

  /* Gold: a fresh marker stroke dragged across the button. It is a marker's shape rather than
     a cut-out's: a rounded chisel end and faint streaks along the drag, not a flat zigzag. It
     runs 44px past the right edge, so the end is never inside the button when the stroke has
     finished; stopping flush left gold notches showing through the old zigzag.

     The fx layer sits above the label for this finish (and only this one), and the stroke
     carries a cream copy of the words that slides the opposite way, so it stays put while the
     ink passes over it. Each letter turns cream exactly as the stroke reaches it (js/cta.js,
     goldStroke). The copy's padding is the button's own plus the stroke's overhang on each
     side, which is what makes the two copies of the words land on the same pixels, and it
     draws its own underline, since the button's ::after would sit under the stroke.

     At night the stroke is sepia rather than ink: a near-black stroke on a near-black desk
     turned the hovered button into an outline with nothing in it. */
  .play-cta:not([data-startbtn]) { --cta-hover-text: #2b2722; --cta-stroke: #2b2722; }
  :root[data-theme="dark"] .play-cta:not([data-startbtn]) { --cta-stroke: #6b4a22; }
  .play-cta:not([data-startbtn]) .cta-fx { z-index: 2; }
  .play-cta:not([data-startbtn])::after { content: none; }
  .cta-stroke { top: -5px; bottom: -5px; left: -5px; right: -44px; overflow: hidden;
    background: repeating-linear-gradient(0deg, #ffffff0c 0 1px, #0000 1px 4px, #0000000f 4px 5px, #0000 5px 7px), var(--cta-stroke);
    border-radius: 0 30px 38px 0 / 0 52% 48% 0;
    transform: translateX(-102%); transition: transform .45s cubic-bezier(.2,.7,.25,1); }
  .cta-stroke-copy { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
    padding: 19px 62px 19px 23px; text-align: center; color: #fff0ce; font-style: normal;
    transform: translateX(102%); transition: transform .45s cubic-bezier(.2,.7,.25,1); }
  .cta-stroke-line { position: absolute; left: calc(5px + (100% - 49px) * .16); right: calc(44px + (100% - 49px) * .16);
    bottom: 14px; height: 2px; border-radius: 2px; background: currentColor; opacity: .7; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-stroke, :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-stroke-copy { transform: translateX(0); }

  /* Ink press: a rubber-stamp impression. The face is matte (the shared white sheen turned a
     near-black slab into grey plastic), the ink has taken unevenly, and on hover fresh ink
     soaks outward from an off-centre point and stays while the button is held, instead of a
     thin ring rippling past and leaving nothing. Hovering sinks it like a stamp meeting paper;
     clicking presses it harder still. */
  .play-cta[data-startbtn="ink"] {
    --cta-fill: #292723; --cta-text: #f6ead2; --cta-hover-text: #efd096;
    --ink-speck: #f6ead2; --ink-bleed: #c9a24d; --ink-edge: #e2bd6b;
    background-image: linear-gradient(168deg, #ffffff0d 0%, #ffffff00 46%, #0000001f 100%);
  }
  /* Night: near-black ink on a near-black desk was about 1.4:1, an outline with nothing in it,
     so at night the stamp is blue-black ink instead, light enough to stand off the desk. Fresh
     ink soaks in darker and wetter there rather than gold, which only greyed on the blue. */
  :root[data-theme="dark"] .play-cta[data-startbtn="ink"] {
    --cta-fill: #4a5a7c; --cta-text: #f3eee2; --cta-hover-text: #f3dfa6;
    --ink-speck: #dfe6f2; --ink-bleed: #141c2e; --ink-edge: #0c1220;
  }
  .cta-ink { inset: 0; width: 100%; height: 100%; }
  .cta-ink-grain { fill: var(--ink-speck); }
  .cta-ink-bleed { transform-box: view-box; transform-origin: 50% 50%; filter: blur(.5px);
    transform: translateX(var(--ink-x, 0px)) rotate(var(--ink-turn, 0deg)); }
  .cta-ink-blot { fill: var(--ink-bleed); fill-opacity: .22; stroke: var(--ink-edge); stroke-opacity: .3; stroke-width: 1.4;
    vector-effect: non-scaling-stroke; transform-box: fill-box; transform-origin: center;
    transform: scale(.2); opacity: 0; transition: opacity .35s ease, transform 0s .35s; }
  :root[data-theme="dark"] .play-cta[data-startbtn="ink"] .cta-ink-blot { fill-opacity: .45; stroke-opacity: .5; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-ink-blot { transform: scale(1); opacity: 1;
    transition: transform 1.1s cubic-bezier(.15,.7,.3,1) var(--ink-delay), opacity .4s ease var(--ink-delay); }
  button.play-cta[data-startbtn="ink"]:is(:hover, :focus-visible) { transform: rotate(-.6deg) translateY(1px); box-shadow: 1px 1px 0 #2b272255, inset 0 2px 5px #0008; }
  button.play-cta[data-startbtn="ink"]:active { transform: rotate(-.6deg) translateY(2px); box-shadow: 0 0 0 #0000, inset 0 3px 8px #000b; }

  /* Blush: a watercolour wash laid across the paper on hover, over two faint dried washes
     that stay at rest. The blotches are drawn shapes (js/cta.js) with a darker tide line at
     the edge, and the whole layer multiplies into the pink, so paint going on deepens the
     colour where it lands and deepest where two blotches overlap, as pigment does, instead of
     bleaching the button. The fill no longer lightens on hover for the same reason. The
     lettering goes to a deep plum over the wash: at most two layers of paint ever overlap,
     and plum holds 5:1 over that. Leaving, the wash fades rather than shrinking back, because
     paint does not un-soak. */
  .play-cta[data-startbtn="rose"] {
    --cta-fill: #e79ab5; --cta-hover-fill: #e79ab5; --cta-hover-text: #2e0f1d;
    --wash: #d0648f; --wash-edge: #b04a78;
  }
  /* Night: a dusk rose with cream lettering; the same wash multiplies it deeper still. */
  :root[data-theme="dark"] .play-cta[data-startbtn="rose"] {
    --cta-fill: #8e4a66; --cta-hover-fill: #8e4a66;
    --cta-text: #f6e8ee; --cta-hover-text: #f6e8ee;
    --wash: #b0668a; --wash-edge: #6d2a4a;
  }
  .play-cta[data-startbtn="rose"] .cta-fx { mix-blend-mode: multiply; }
  /* A slight blur turns each blotch's edge line into a pooled edge rather than an outline. */
  .cta-wash { inset: 0; width: 100%; height: 100%; filter: blur(.55px); }
  .cta-wash path { fill: var(--wash); stroke: var(--wash-edge); stroke-width: 1.8; vector-effect: non-scaling-stroke; }
  .cta-wash-dried path { fill-opacity: .13; stroke-opacity: .18; }
  .cta-wash-live { transform-box: view-box; transform-origin: 50% 50%;
    transform: translateX(var(--wash-x, 0px)) rotate(var(--wash-turn, 0deg)); }
  .cta-wash-blot { fill-opacity: .32; stroke-opacity: .3; transform-box: fill-box; transform-origin: center;
    transform: scale(.3); opacity: 0; transition: opacity .3s ease, transform 0s .3s; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-wash-blot { transform: scale(1); opacity: 1;
    transition: transform 1s cubic-bezier(.2,.7,.3,1) var(--wash-delay), opacity .45s ease var(--wash-delay); }

  /* Sky: fair-weather clouds along the top edge give way to a storm front of their own on
     hover. The two are separate layers so one can fade out while the other rolls in; the old
     clouds were a background image, which cannot fade, and simply vanished, leaving a bare sky
     for half a second. The rain has two depths, irregular spacing, short trails and staggered
     arrivals, never a striped veil, and is thinned rather than removed behind the lettering.
     One branching discharge has a thin white core and a softer blue halo, placed by
     placeStrike in js/cta.js so it never lands on the label. No repeating flash. */
  .play-cta[data-startbtn="sky"] {
    --cta-fill: #7fb0dd; --cta-hover-fill: #263b53; --cta-hover-text: #faf0da;
    --day-cloud: #fff; --storm-back: #3f546c; --storm-front: #17222f; --rain: #d8e8f7;
  }
  /* Night: a clear night sky with dim clouds instead of a bright daytime slab on the dark desk;
     the storm then only has to darken it a step further. */
  :root[data-theme="dark"] .play-cta[data-startbtn="sky"] {
    --cta-fill: #2f4a66; --cta-hover-fill: #1b2837;
    --cta-text: #f3ecd6; --cta-hover-text: #f3ecd6;
    --day-cloud: #b9c9d8; --storm-back: #33465b; --storm-front: #0f1822;
  }
  .cta-day-clouds { inset: 0; width: 100%; height: 100%; fill: var(--day-cloud);
    transition: opacity .45s ease, transform 1.2s ease; }
  :root[data-theme="dark"] .play-cta[data-startbtn="sky"] .cta-day-clouds { opacity: .45; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-day-clouds { opacity: 0 !important; transform: translateX(14px); }
  .cta-storm-clouds { top: -4px; left: -30px; width: calc(100% + 60px); height: 36px; opacity: 0;
    transform: translateX(-24px); transition: opacity .5s ease .1s, transform 1.2s ease; }
  .cta-storm-back { fill: var(--storm-back); }
  .cta-storm-front { fill: var(--storm-front); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-storm-clouds { opacity: 1; transform: translateX(0); }
  .cta-rain { inset: 0; opacity: 0; overflow: hidden;
    mask-image: linear-gradient(90deg, #000 0 15%, #0007 36% 65%, #000 85%); }
  .cta-rain--far { filter: blur(.3px); }
  .cta-drop { position: absolute; top: -18px; width: 1.2px; height: var(--drop-h);
    background: linear-gradient(transparent, var(--rain)); border-radius: 50%; opacity: 0; transform: rotate(16deg); }
  .cta-rain--far .cta-drop { width: .8px; height: calc(var(--drop-h) * .65); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-rain { animation: ctaRainShower 2.6s ease-out both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-drop { animation: ctaRainFall var(--drop-duration) var(--drop-delay) linear 4; }
  @keyframes ctaRainShower { 0% { opacity: 0; } 12%, 75% { opacity: 1; } 100% { opacity: 0; } }
  @keyframes ctaRainFall { 0% { opacity: 0; transform: translate(8px, var(--drop-y)) rotate(16deg); }
    15%, 75% { opacity: .95; } 100% { opacity: 0; transform: translate(-12px, calc(var(--drop-y) + 82px)) rotate(16deg); } }
  .cta-lightning { left: var(--cta-bolt-left, 0px); top: -3px; width: var(--cta-bolt-w, 43px); height: calc(100% + 6px); opacity: 0;
    fill: none; stroke-linecap: round; stroke-linejoin: round; }
  .cta-no-bolt .cta-lightning { display: none; }
  .cta-bolt-halo { stroke: #a3c8ff; stroke-width: 3; filter: blur(2px); }
  .cta-bolt-core { stroke: #f6faff; stroke-width: 1.1; }
  .cta-bolt-branch { stroke: #d5e6ff; stroke-width: .55; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-lightning { animation: ctaLightning 1.1s .45s ease-out both; }
  @keyframes ctaLightning { 0%, 8% { opacity: 0; } 11% { opacity: .95; } 22% { opacity: .55; } 45% { opacity: .18; } 100% { opacity: 0; } }

  /* Meadow: rooted blades bend once in a passing breeze; the flowers stay open. */
  .play-cta[data-startbtn="meadow"] {
    /* Hover warms the green into sunlight rather than bleaching it: the old pale hover
       washed out the cream daisy and lilac flowers at the very moment they came up. */
    --cta-fill: #82b061; --cta-hover-fill: #8fbb67; --cta-hover-text: #263c26;
    --blade-a: #466b3e; --blade-b: #5d8449;
  }
  /* Night: a dusk meadow rather than the daytime lawn, which was a bright slab on the dark
     desk. The back blades turn pale so the grass catches the light instead of vanishing. */
  :root[data-theme="dark"] .play-cta[data-startbtn="meadow"] {
    --cta-fill: #4e6e3d; --cta-hover-fill: #466435;
    --cta-text: #f3ecd6; --cta-hover-text: #f3ecd6;
    --blade-a: #2c4527; --blade-b: #7a9a62;
  }
  .cta-garden { bottom: 0; left: 0; width: 100%; height: 30px; overflow: visible; }
  .cta-blade { stroke: var(--blade-a); fill: none; stroke-linecap: round; transform-box: fill-box; transform-origin: 50% 100%; }
  .cta-blade--back { stroke: var(--blade-b); }
  .cta-flower { bottom: 0; width: 18px; height: 27px; overflow: visible; transform: translateY(100%);
    transition: transform .65s cubic-bezier(.25,.8,.25,1); transition-delay: var(--flower-delay); }
  .cta-flower-stem { fill: none; stroke: var(--blade-a); stroke-width: 1.3; stroke-linecap: round; }
  .cta-flower-sway { transform-box: fill-box; transform-origin: 50% 100%; }
  .cta-petals { fill: var(--flower-colour, #faf0cc); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flower { transform: translateY(0); }
  /* The breeze crosses left to right, blade by blade, and the flowers bend in it too, a beat
     after they have come up. */
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-blade { animation: ctaBreeze 1s var(--wind-delay) ease-in-out 2; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flower-sway { animation: ctaFlowerSway 1s calc(.55s + var(--wind-delay)) ease-in-out 2; }
  @keyframes ctaBreeze { 0%, 100% { transform: skewX(0); } 40% { transform: skewX(12deg); } 75% { transform: skewX(-6deg); } }
  @keyframes ctaFlowerSway { 0%, 100% { transform: rotate(0); } 40% { transform: rotate(-7deg); } 75% { transform: rotate(3deg); } }

  /* The Seasons finish: one Mastery pick that wears four finishes, spring, summer, autumn and
     winter, resolved from the month and the player's hemisphere (js/season.js) and drawn in
     js/cta.js. Four sets of rules rather than one, because each season is its own material,
     but one grammar: a quiet scene at rest, and on hover that season's weather arrives, runs
     for a few seconds and holds its end state. Winter replaced the old Snowfall finish. */
  .play-cta:is([data-startbtn="spring"], [data-startbtn="summer"], [data-startbtn="autumn"], [data-startbtn="winter"])::after { content: none; }
  /* =====================================================================
     SPRING: Blossom
     A cherry bough reaches in from the top-left and a second, sparer sprig
     hangs from the top-right. At rest most of it is still in bud. On hover
     the buds open one after another, the boughs give in the breeze, and
     petals come off and ride the wind across and down, tumbling as they
     go. Some land and stay on the sill, the way the snow settles.
     ===================================================================== */
  .play-cta[data-startbtn="spring"] {
    --cta-fill: #c8dcc0; --cta-hover-fill: #d0e3c6; --cta-text: #283a2b; --cta-hover-text: #283a2b;
    --bark: #4e3c35; --petal-edge: #d98ea6; --eye: #c65f80; --bud: #ec9fb6; --calyx: #7c9a62;
    --cta-art: radial-gradient(ellipse 60% 90% at 12% 0, #ffffff55, transparent 70%);
    padding-inline: clamp(18px, 9%, 48px);
  }
  :root[data-theme="dark"] .play-cta[data-startbtn="spring"] {
    --cta-fill: #5c7465; --cta-hover-fill: #627a6b; --cta-text: #f4efe4; --cta-hover-text: #f4efe4;
    --bark: #241c19; --cta-art: radial-gradient(ellipse 60% 90% at 12% 0, #ffffff14, transparent 70%);
  }
  .cta-bough { top: 0; height: auto; overflow: visible; }
  .cta-bough--left { left: 0; width: clamp(82px, 28%, 150px); }
  .cta-bough--right { right: 0; width: clamp(58px, 19%, 104px); }
  .cta-wood { fill: var(--bark); }
  .cta-petal-vein path { stroke: #d98ea6; stroke-width: .4; stroke-linecap: round; opacity: .55; }
  .cta-anther { fill: #b0476a; }
  .cta-bough-sway { transition: transform 1s cubic-bezier(.3,.7,.3,1); }
  .cta-bough--left .cta-bough-sway { transform-origin: 0 0; }
  .cta-bough--right .cta-bough-sway { transform-origin: 100% 0; }
  .cta-bark { fill: none; stroke: var(--bark); stroke-linecap: round; stroke-linejoin: round; }
  .cta-bloom path { stroke: var(--petal-edge); stroke-width: .45; }
  .cta-bloom-eye { fill: var(--eye); }
  .cta-stamen { stroke: #a8506c; stroke-width: .5; fill: none; }
  .cta-bud-shape { fill: var(--bud); stroke: var(--petal-edge); stroke-width: .4; }
  .cta-calyx { fill: var(--calyx); }
  .cta-opens, .cta-bud { transform-box: fill-box; transform-origin: 50% 50%; }
  .cta-opens { transform: scale(.15) rotate(-50deg); opacity: 0;
    transition: transform .3s ease, opacity .2s ease; }
  .cta-bud { transition: transform .3s ease .1s, opacity .3s ease .1s; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-opens {
    transform: scale(1) rotate(0); opacity: 1;
    transition: transform .7s cubic-bezier(.2,.9,.3,1.15) var(--open-at), opacity .35s ease var(--open-at); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-bud {
    transform: scale(.2); opacity: 0; transition: transform .4s ease var(--open-at), opacity .3s ease var(--open-at); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-bough--left .cta-bough-sway { animation: ctaBoughL 1.8s .35s ease-in-out 2; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-bough--right .cta-bough-sway { animation: ctaBoughR 1.9s .55s ease-in-out 2; }
  @keyframes ctaBoughL { 0%, 100% { transform: rotate(0); } 35% { transform: rotate(2.2deg); } 70% { transform: rotate(-.8deg); } }
  @keyframes ctaBoughR { 0%, 100% { transform: rotate(0); } 40% { transform: rotate(-2.6deg); } 72% { transform: rotate(1deg); } }

  .cta-petalfall { inset: 0 0 3px; overflow: hidden; }
  .cta-petal { position: absolute; width: var(--ps); height: var(--ps); opacity: 0; }
  .cta-petal b { display: block; width: 100%; height: 72%; background: var(--pc);
    border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%; box-shadow: inset -.6px -.6px 0 #d98ea655; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-petal {
    animation: ctaPetalRide var(--pt) var(--pd) cubic-bezier(.35,.15,.6,.95) 2; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-petal b {
    animation: ctaPetalTumble var(--pf) var(--pd) linear 4; }
  @keyframes ctaPetalRide {
    0% { opacity: 0; transform: translate(0, 0); }
    7% { opacity: 1; }
    30% { transform: translate(calc(var(--px) * .22 + var(--pw)), 15px); }
    58% { transform: translate(calc(var(--px) * .58 - var(--pw)), 33px); }
    86% { opacity: .95; }
    100% { opacity: 0; transform: translate(var(--px), 60px); }
  }
  @keyframes ctaPetalTumble {
    0% { transform: rotate(var(--pr)) rotate3d(1, .35, 0, 0deg); }
    100% { transform: rotate(calc(var(--pr) + 160deg)) rotate3d(1, .35, 0, 360deg); }
  }
  .cta-sill { left: 0; bottom: 0; width: 100%; height: 9px; }
  .cta-sill-late { opacity: 0; transition: opacity .3s ease; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-sill-late { opacity: 1; transition: opacity .5s ease var(--land); }

  /* =====================================================================
     SUMMER: Tide
     ===================================================================== */
  .play-cta[data-startbtn="summer"] {
    --cta-fill: #52b9bd; --cta-hover-fill: #52b9bd; --cta-text: #0d3337; --cta-hover-text: #0d3337;
    --cta-art: linear-gradient(180deg, #dcf3f1 0 22%, #2e93a0 22% 24.5%, #3aa5ae 24.5%, #4fb7bb 55%, #6ccac7 100%);
    --sand-dry: #f1dca8; --sand-wet: #dfc690; --sand-soak: #cfb07a; --foam: #ffffff; --sea-edge: #64c4c3; --shallows: #a3e1d6; --gull: #35565b; --glint: #ffffff;
    background-image: linear-gradient(168deg, #ffffff30 0%, #ffffff00 46%, #0000001a 100%), var(--cta-art);
  }
  :root[data-theme="dark"] .play-cta[data-startbtn="summer"] {
    --cta-fill: #1c5664; --cta-hover-fill: #1c5664; --cta-text: #eef8f6; --cta-hover-text: #eef8f6;
    --cta-art: linear-gradient(180deg, #1b2c42 0 22%, #0c3441 22% 24.5%, #144655 24.5%, #1b5867 55%, #236877 100%);
    --sand-dry: #a99a7a; --sand-wet: #928467; --sand-soak: #7e7157; --foam: #dbe9ea; --sea-edge: #216575; --shallows: #3a8791; --gull: #c9d6dc; --glint: #e6eef8;
    background-image: linear-gradient(168deg, #ffffff12 0%, #ffffff00 46%, #0000002e 100%), var(--cta-art);
  }
  :root[data-theme="dark"] .play-cta[data-startbtn="summer"] .cta-label { text-shadow: 0 1px 2px #0b2a31; }
  .cta-sand { left: 0; bottom: 0; width: 100%; height: 20px; }
  .cta-sand-dry { fill: var(--sand-dry); }
  .cta-sand-damp { fill: var(--sand-wet); }
  .cta-sand-soak { fill: var(--sand-soak); opacity: 0; }
  .cta-lace-left { fill: var(--foam); opacity: 0; }
  .cta-lace-left path { fill: none; stroke: var(--foam); stroke-width: .7; stroke-dasharray: 5 3 2 4 9 3; }
  .cta-surf { left: 0; bottom: 0; width: 100%; height: 29px; }
  .cta-surf-deep { stop-color: var(--sea-edge); }
  .cta-surf-shallow { stop-color: var(--shallows); }
  .cta-surf-lip { fill: none; stroke: var(--foam); stroke-width: 2.1; stroke-linecap: round; stroke-linejoin: round; }
  .cta-surf-trail path { fill: none; stroke: var(--foam); stroke-linecap: round; opacity: .75; }
  .cta-surf-bubbles { fill: var(--foam); opacity: .8; }
  /* Rushes up quickly, hangs, draws back slowly: the swash is fast and the backwash is not. */
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-surf { animation: ctaSwash 2.9s .15s linear 2; }
  @keyframes ctaSwash {
    0% { transform: translateY(0); animation-timing-function: cubic-bezier(.2,.7,.35,1); }
    38% { transform: translateY(5px); animation-timing-function: ease-in-out; }
    48% { transform: translateY(5.2px); animation-timing-function: cubic-bezier(.5,.1,.6,1); }
    100% { transform: translateY(0); }
  }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-surf-trail { animation: ctaTrail 2.9s .15s ease-in-out 2; }
  @keyframes ctaTrail { 0%, 100% { opacity: .75; } 40% { opacity: .95; } 70% { opacity: .35; } }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-sand-soak { animation: ctaSoak 2.9s .15s linear 2; }
  @keyframes ctaSoak { 0%, 40% { opacity: 0; } 50% { opacity: 1; } 100% { opacity: 0; } }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-lace-left { animation: ctaLaceLeft 2.9s .15s linear 2; }
  @keyframes ctaLaceLeft { 0%, 46% { opacity: 0; } 54% { opacity: .9; } 85%, 100% { opacity: 0; } }
  .cta-glint { height: 1.4px; border-radius: 1px; background: var(--glint); opacity: var(--g0); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-glint { animation: ctaGlint 1s var(--gd) ease-in-out 5 alternate; }
  @keyframes ctaGlint { 0% { opacity: var(--g0); transform: scaleX(1); } 100% { opacity: 1; transform: scaleX(1.7); } }
  .cta-boat { left: 66%; top: calc(23% - 12px); width: 17px; height: 13px; transition: transform .8s ease; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-boat { transform: translateX(26px); transition: transform 7s linear; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-boat path { animation: ctaBob 1.4s ease-in-out 4 alternate; }
  @keyframes ctaBob { 0% { transform: translateY(0); } 100% { transform: translateY(.6px); } }
  .cta-gull { width: 12px; height: 5px; transition: transform .8s ease; }
  .cta-gull--a { left: 14%; top: 3px; }
  .cta-gull--b { left: 21%; top: 7px; width: 9px; }
  .cta-gull path { transform-box: fill-box; transform-origin: 50% 70%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-gull { transform: translate(18px, -1px); transition: transform 4s ease-out; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-gull path { animation: ctaFlap .32s ease-in-out 8 alternate; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-gull--b path { animation-delay: .12s; }
  @keyframes ctaFlap { 0% { transform: scaleY(1); } 100% { transform: scaleY(-.5); } }
  .cta-starfish { left: 7%; bottom: 0; width: 12px; height: 12px; transform: rotate(-14deg); }
  .cta-shell { right: 10%; bottom: 0; width: 11px; height: 10px; transform: rotate(9deg); }

  /* =====================================================================
     AUTUMN: Gust
     Woodland green with the year's leaves banked up in both corners and a
     few strays along the sill, and one twig still holding its last three.
     On hover a gust comes through from the left: curls of wind drawn in
     the air, leaves tumbling across the face, the heaps rustling in the
     order the wind reaches them, and two of the twig's leaves letting go
     and coming to rest on the sill. The third holds on.
     ===================================================================== */
  .play-cta[data-startbtn="autumn"] {
    --cta-fill: #3d5646; --cta-hover-fill: #425c4b; --cta-text: #f7ecd4; --cta-hover-text: #f7ecd4;
    --wind: #f3e3c3; --twig: #2a1f19; --litter: #6b3a22;
    --cta-art: radial-gradient(ellipse 50% 110% at 85% 0, #ffffff12, transparent 70%);
    background-image: linear-gradient(168deg, #ffffff1c 0%, #ffffff00 46%, #0000002a 100%), var(--cta-art);
  }
  :root[data-theme="dark"] .play-cta[data-startbtn="autumn"] {
    --cta-fill: #3a5243; --cta-hover-fill: #3e5747; --wind: #e9dcc0; --litter: #54301c;
  }
  .play-cta[data-startbtn="autumn"] .cta-label { text-shadow: 0 1px 2px #1d2b22; }
  .play-cta[data-startbtn="autumn"] .cta-fx { container-type: size; }
  .cta-leaf-v { fill: none; stroke-linecap: round; stroke-linejoin: round; }
  .cta-litter { left: 0; bottom: 0; width: 100%; height: 22px; overflow: visible; }
  .cta-litter-bed { fill: var(--litter); }
  .cta-twig-wood { fill: var(--twig); }
  .cta-heap-leaf { transform-box: fill-box; transform-origin: 50% 80%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-heap-leaf { animation: ctaRustle .55s var(--rd) ease-in-out 2 alternate; }
  @keyframes ctaRustle { 0% { transform: rotate(0) translateY(0); } 100% { transform: rotate(var(--rt)) translateY(-1.4px); } }
  .cta-winds { inset: 0; width: 100%; height: 100%; }
