    stroke-dasharray: 100 100; stroke-dashoffset: 100; vector-effect: non-scaling-stroke; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-wind { animation: ctaWind var(--wt) var(--wd) cubic-bezier(.4,.1,.5,1) both; }
  @keyframes ctaWind { 0% { stroke-dashoffset: 100; opacity: .55; } 55% { stroke-dashoffset: 0; opacity: .5; } 100% { stroke-dashoffset: -100; opacity: 0; } }
  .cta-gust { width: var(--gs); height: var(--gs); left: calc(var(--gs) * -1.4); top: var(--gy0); }
  .cta-gust svg, .cta-fall svg { display: block; width: 100%; height: 100%; overflow: visible; }
  .cta-gust > span, .cta-fall > span { display: block; width: 100%; height: 100%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-gust { animation: ctaGustAcross var(--gt) var(--gd) cubic-bezier(.3,.05,.55,1) both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-gust > span { animation: ctaLeafTumble var(--gf) var(--gd) linear 4; }
  @keyframes ctaGustAcross {
    0% { transform: translate(0, 0); }
    30% { transform: translate(38cqw, var(--gy1)); }
    62% { transform: translate(72cqw, var(--gy2)); }
    100% { transform: translate(calc(100cqw + var(--gs) * 3), var(--gy3)); }
  }
  @keyframes ctaLeafTumble {
    0% { transform: rotate(var(--gr)) rotate3d(.4, 1, .15, 0deg); }
    100% { transform: rotate(calc(var(--gr) + 220deg)) rotate3d(.4, 1, .15, 360deg); }
  }
  .cta-twig { right: 4px; top: 0; width: 76px; height: 40px; }
  .cta-twig > svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .cta-twig-sway { transform-origin: 72px 0; }
  /* On a phone the label runs nearly edge to edge, so the twig hangs from further out. */
  @container (max-width: 330px) { .cta-twig { right: -18px; top: -3px; } }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-twig-sway { animation: ctaTwig 1.4s .15s ease-in-out 2; }
  @keyframes ctaTwig { 0%, 100% { transform: rotate(0); } 30% { transform: rotate(-5deg); } 65% { transform: rotate(2deg); } }
  .cta-fall { position: absolute; width: var(--fs); height: var(--fs); left: var(--fx); top: var(--fy); margin: calc(var(--fs) / -2) 0 0 calc(var(--fs) / -2); }
  .cta-fall > span { transform: rotate(var(--fr0)); transform-origin: 50% 10%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-fall { animation: ctaLetGo var(--ft) var(--fd) cubic-bezier(.45,.05,.6,1) both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-fall > span { animation: ctaLetGoSpin var(--ft) var(--fd) ease-in-out both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-fall--holds > span { animation: ctaHoldOn .5s .25s ease-in-out 3 alternate; }
  @keyframes ctaLetGo {
    0% { transform: translate(0, 0); }
    25% { transform: translate(calc(var(--lx) * .35), calc((100cqh - var(--fy) - var(--ly)) * .22)); }
    55% { transform: translate(calc(var(--lx) * .5), calc((100cqh - var(--fy) - var(--ly)) * .6)); }
    80% { transform: translate(calc(var(--lx) * .85), calc((100cqh - var(--fy) - var(--ly)) * .88)); }
    100% { transform: translate(var(--lx), calc(100cqh - var(--fy) - var(--ly))); }
  }
  @keyframes ctaLetGoSpin {
    0% { transform: rotate(var(--fr0)) rotate3d(.3, 1, 0, 0deg); }
