    100% { transform: rotate(var(--fr1)) rotate3d(.3, 1, 0, 360deg); }
  }
  @keyframes ctaHoldOn { 0% { transform: rotate(var(--fr0)); } 100% { transform: rotate(calc(var(--fr0) - 16deg)); } }
  /* =====================================================================
     WINTER: Snowstorm
     Ice blue with two drifts on the sill, the back one a shade darker, and
     hoarfrost feathered in from both top corners. On hover the storm comes
     in: the sky goes to slate, snow blows through on a slant in three
     depths (soft far flakes, a middle layer that lands in the drift, and a
     few big near crystals that turn as they pass), two gusts of whiteout
     sweep across, the frost creeps further in and the drifts build. The
     snow blows itself out in about five seconds; the frost and the deeper
     drifts stay while the pointer does.
     ===================================================================== */
  .play-cta[data-startbtn="winter"] {
    --cta-fill: #a8c6d7; --cta-hover-fill: #a8c6d7; --cta-text: #22394a; --cta-hover-text: #f5f9fb;
    --cta-art: radial-gradient(ellipse 20% 75% at 0 0, #ffffff85, transparent 72%), radial-gradient(ellipse 15% 65% at 100% 0, #ffffff70, transparent 72%), radial-gradient(ellipse at 30% 0, #ffffff40, transparent 60%);
    --storm-sky: linear-gradient(180deg, #33485a 0%, #4b687c 55%, #7391a4 100%);
    --frost: #ffffff; --drift-back: #d3e3eb; --drift-front: #f7fbfc; --drift-line: #b7cfdb; --whiteout: #ffffffa8;
    background-image: linear-gradient(168deg, #ffffff2e 0%, #ffffff00 46%, #2b27221f 100%), var(--cta-art);
    transition: background-color .45s ease, color .6s ease .3s, transform .2s, box-shadow .2s;
  }
  :root[data-theme="dark"] .play-cta[data-startbtn="winter"] {
    --cta-fill: #3e5a6c; --cta-hover-fill: #3e5a6c; --cta-text: #eef4f6; --cta-hover-text: #f5f9fb;
    --cta-art: radial-gradient(ellipse 20% 75% at 0 0, #ffffff2e, transparent 72%), radial-gradient(ellipse 15% 65% at 100% 0, #ffffff24, transparent 72%), radial-gradient(ellipse at 30% 0, #ffffff14, transparent 60%);
    --storm-sky: linear-gradient(180deg, #131d25 0%, #1f303c 55%, #33505f 100%);
    --frost: #dfeaf0; --drift-back: #9db4bf; --drift-front: #d7e3e8; --drift-line: #88a1ad; --whiteout: #dfe9ef66;
    background-image: linear-gradient(168deg, #ffffff14 0%, #ffffff00 46%, #0000002e 100%), var(--cta-art);
  }
  .play-cta[data-startbtn="winter"] .cta-fx { container-type: size; }
  .play-cta[data-startbtn="winter"] .cta-label { transition: text-shadow .6s ease .3s; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta)[data-startbtn="winter"] .cta-label { text-shadow: 0 1px 3px #16222b; }
  .cta-storm-sky { inset: 0; background: var(--storm-sky); opacity: 0; transition: opacity .9s ease; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-storm-sky { opacity: .95; transition: opacity 1.1s ease .05s; }
  .cta-frost { top: 0; height: auto; overflow: visible; }
  .cta-frost--left { left: 0; width: clamp(64px, 22%, 110px); }
  .cta-frost--right { right: 0; width: clamp(52px, 18%, 96px); }
  .cta-frost path { fill: none; stroke: var(--frost); stroke-linecap: round; opacity: .92;
    stroke-dasharray: 1 1; stroke-dashoffset: var(--rest); transition: stroke-dashoffset .6s ease; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-frost path { stroke-dashoffset: 0; transition: stroke-dashoffset 2.4s cubic-bezier(.3,.6,.4,1) var(--fz); }
  .cta-flurry { inset: 0; overflow: hidden; opacity: 0; transition: opacity .5s ease; }
  .cta-flurry--mid { inset: 0 0 5px; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flurry { opacity: 1; transition: none; }
  .cta-flake { position: absolute; top: 0; left: 0; width: var(--fsz); height: var(--fsz); border-radius: 50%; background: #fff; opacity: 0; }
  .cta-flurry--far .cta-flake { background: #eef5f9; filter: blur(.45px); }
  .cta-flake--crystal { background: none; border-radius: 0; }
  .cta-flake svg { display: block; width: 100%; height: 100%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flake { animation: ctaBlow var(--ft) var(--fd) linear var(--fn); }
  @keyframes ctaBlow {
    0% { opacity: 0; transform: translate(var(--x0), -12px) rotate(0); }
    10% { opacity: .95; }
    50% { transform: translate(calc(var(--x0) + var(--fw) * .5 + var(--fsway)), calc(50cqh - 6px)) rotate(calc(var(--fspin) * .5)); }
    88% { opacity: .95; }
    100% { opacity: 0; transform: translate(calc(var(--x0) + var(--fw)), calc(100cqh + 4px)) rotate(var(--fspin)); }
  }
  .cta-whiteout { top: -30%; bottom: -30%; left: 0; width: 55cqw; opacity: 0; transform: translateX(-60cqw);
    background: radial-gradient(ellipse 50% 50% at 50% 50%, var(--whiteout), #fff0 72%); filter: blur(2px); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-whiteout { animation: ctaWhiteout 1.5s .7s ease-in-out both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-whiteout--2 { animation-duration: 1.9s; animation-delay: 2.5s; }
  @keyframes ctaWhiteout { 0% { opacity: 0; transform: translateX(-60cqw); } 30%, 65% { opacity: .8; } 100% { opacity: 0; transform: translateX(105cqw); } }
  .cta-drifts { left: 0; bottom: 0; width: 100%; height: 24px; transform-origin: 50% 100%; transition: transform .6s ease; }
  .cta-drifts--back path { fill: var(--drift-back); }
  .cta-drifts--front path { fill: var(--drift-front); }
  .cta-drifts--front .cta-drift-line { fill: none; stroke: var(--drift-line); stroke-width: 1; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-drifts--back { transform: scaleY(1.22); transition: transform 4s cubic-bezier(.3,.5,.4,1) .8s; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-drifts--front { transform: scaleY(1.32); transition: transform 4.4s cubic-bezier(.3,.5,.4,1) 1.1s; }

  /* Ivy is deliberately allowed out of the frame, like a cutting laid on brick. The brick is
     dark enough to carry cream lettering at 4.8:1, and a soft shade sits under the label so the
     pale mortar never runs through the letters at full strength. The tile is four courses of
     four bricks, each its own tone with its joints a pixel or two off true, so the wall reads
     as laid by hand rather than stamped from one repeating pair. */
  .play-cta[data-startbtn="ivy"] {
    --cta-fill: #9a5f4b; --cta-hover-fill: #874f3e;
    --cta-text: #fff6df; --cta-hover-text: #fff6df;
    --cta-art: radial-gradient(ellipse 46% 62% at 50% 50%, #3b1d145e, #3b1d1400), url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='192' height='64' viewBox='0 0 192 64'><rect x='1' y='1' width='45' height='14' fill='%233a1a10' opacity='0.12'/><rect x='48' y='1' width='48' height='14' fill='%233a1a10' opacity='0.17'/><rect x='98' y='1' width='43' height='14' fill='%233a1a10' opacity='0.06'/><rect x='27' y='17' width='45' height='14' fill='%233a1a10' opacity='0.06'/><rect x='74' y='17' width='44' height='14' fill='%233a1a10' opacity='0.12'/><rect x='120' y='17' width='46' height='14' fill='%23fff' opacity='0.05'/><rect x='168' y='17' width='49' height='14' fill='%233a1a10' opacity='0.12'/><rect x='-24' y='17' width='49' height='14' fill='%233a1a10' opacity='0.12'/><rect x='1' y='33' width='47' height='14' fill='%233a1a10' opacity='0.06'/><rect x='50' y='33' width='46' height='14' fill='%233a1a10' opacity='0.12'/><rect x='98' y='33' width='46' height='14' fill='%23fff' opacity='0.09'/><rect x='146' y='33' width='45' height='14' fill='%23fff' opacity='0.05'/><rect x='24' y='49' width='46' height='14' fill='%233a1a10' opacity='0.06'/><rect x='72' y='49' width='46' height='14' fill='%233a1a10' opacity='0.17'/><rect x='120' y='49' width='48' height='14' fill='%233a1a10' opacity='0.12'/><rect x='170' y='49' width='44' height='14' fill='%23fff' opacity='0.09'/><path d='M7 5H38M55 4H91M100 5H132M147 5H187M33 21H69M79 20H115M122 20H160M172 20H212M-18 21H19M4 36H42M52 36H93M102 37H137M153 36H182M26 52H62M74 52H113M126 52H164M173 53H205M-19 52H19' stroke='%237e4d40' opacity='.3'/><path d='M0 0H192M0 16H192M0 32H192M0 48H192M0 64H192M0 0V16M192 0V16M47 0V16M97 0V16M142 0V16M26 16V32M73 16V32M119 16V32M167 16V32M0 32V48M192 32V48M49 32V48M97 32V48M145 32V48M23 48V64M71 48V64M119 48V64M169 48V64' fill='none' stroke='%23d2ae8f' stroke-width='2'/></svg>");
    /* The vines own the corners, so the label keeps out of their reach at every width. */
    padding-inline: clamp(18px, 10%, 52px);
  }
  .play-cta[data-startbtn="ivy"]::after { content: none; }
  .play-cta[data-startbtn="ivy"] .cta-label { text-shadow: 0 1px 2px #482b20; }
  .play-cta[data-startbtn="ivy"] .cta-fx { overflow: visible; }
  /* Sized off the button, but pinned by the root to its own bottom corner, so a narrow phone
     button gets a smaller vine still growing from the corner rather than one floating mid-face. */
  .cta-ivy { top: auto; bottom: -6px; left: -9px; width: clamp(54px, 29%, 110px); height: auto; overflow: visible; filter: drop-shadow(1px 2px 1px #24361b44); }
  .cta-ivy--right { left: auto; right: -8px; bottom: -5px; width: clamp(46px, 25%, 96px); }
  /* Ivy clings, so the stem barely stirs; the breeze is in the leaves, turning one after
     another and settling part of the way back. */
  .cta-ivy-stem { transition: transform .7s cubic-bezier(.22,.75,.3,1); }
  .cta-ivy-leaf { transform-box: fill-box; transform-origin: 50% 90%; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-ivy--left .cta-ivy-stem { transform: rotate(-4deg); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-ivy--right .cta-ivy-stem { transform: rotate(3deg); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-ivy-leaf { animation: ctaIvyRustle .9s var(--ivy-delay) cubic-bezier(.3,.6,.35,1) both; }
  @keyframes ctaIvyRustle { 0% { transform: rotate(0); } 35% { transform: rotate(var(--ivy-turn)); } 70% { transform: rotate(calc(var(--ivy-turn) * -.3)); } 100% { transform: rotate(calc(var(--ivy-turn) * .5)); } }

  /* Pride: all eight flags still come only from PRIDE_BUTTONS (js/config.js), in their own
     colours and proportions, at full strength behind the label. A pale patch under the words
     was tried and taken off: the dark label reads across every flag without it, and the patch
     only washed the middle of each flag out to pastel.

     On hover the cloth itself waves. The fx layer holds the flag again cut into thin upright
     slices (js/cta.js, prideRipple), each showing its own sliver of the one --cta-stripes ramp,
     and each slice rides up and down a little after the one to its left, so a wave runs from
     the hoist out to the fly. It grows as it goes (--a, set per slice), since a flag is pinned
     at the pole and loose at the far end, and each slice catches light on the way up and shade
     on the way down. Two waves, then it hangs still. The words never move.

     A slice that has ridden up or down uncovers the button's own flag behind it, whose top and
     bottom edges are the same first and last bands, so the wave never opens a gap. The slices
     cover the button's sheen, so the layer draws it again on top (.cta-flag-sheen), which keeps
     the face the same at rest and while held. A slice's width must stay exactly 1/n of the
     button: background-size is a percentage of the slice, so any overlap added to hide seams
     stretches every sliver and the flag tears into stripes. */
  .play-cta[data-startbtn^="pride-"] {
    --cta-hover-text: #2b2722;
    --cta-art: var(--cta-stripes);
  }
  /* The one flag that letters in white. The words cross the bisexual flag's purple and the top
     of its blue, where dark ink falls to 1.5:1; white holds 5.1:1 across both. Every other flag
     has a white or pale stripe behind the words, where white lettering would vanish, so the
     rest stay dark. */
  .play-cta[data-startbtn="pride-bi"] { --cta-text: #fff; --cta-hover-text: #fff; }
  @property --cta-wave-y { syntax: "<length>"; inherits: false; initial-value: 0px; }
  @property --cta-wave-shade { syntax: "<color>"; inherits: false; initial-value: #0000; }
  .cta-flag-slice { top: 0; bottom: 0; left: calc(var(--i) * 100% / var(--n)); width: calc(100% / var(--n));
    background-image: var(--cta-stripes); background-repeat: no-repeat;
    background-size: calc(var(--n) * 100%) 100%;
    background-position: calc(var(--i) / (var(--n) - 1) * 100%) var(--cta-wave-y); }
  .cta-flag-slice::after { content: ""; position: absolute; inset: 0; background: var(--cta-wave-shade); }
  .cta-flag-sheen { inset: 0; background: linear-gradient(168deg, #ffffff57 0%, #ffffff00 46%, #2b27221f 100%); }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flag-slice { animation: ctaFlagWave 1.15s calc(var(--i) / var(--n) * 1.1s) cubic-bezier(.45,0,.55,1) 2 both; }
  :is(.play-cta:hover, .play-cta:focus-visible, .bc-cell:hover .play-cta, .bc-cell:focus-visible .play-cta) .cta-flag-slice::after { animation: ctaFlagShade 1.15s calc(var(--i) / var(--n) * 1.1s) cubic-bezier(.45,0,.55,1) 2 both; }
  @keyframes ctaFlagWave { 0%, 100% { --cta-wave-y: 0px; } 25% { --cta-wave-y: calc(var(--a) * -1px); } 75% { --cta-wave-y: calc(var(--a) * 1px); } }
  @keyframes ctaFlagShade { 0%, 50%, 100% { --cta-wave-shade: #0000; } 12% { --cta-wave-shade: #ffffff30; } 62% { --cta-wave-shade: #00000026; } }

  /* ---------- Album anniversaries ----------
     The sixteen finishes the Start writing button is made to wear on each studio album's release
     day and each Taylor's Version's (anniversaryFinishFor in js/anniversarycta.js decides the day,
     and says why it overrides the player's own pick). Each rides the ordinary .play-cta: the label,
     the ink border, the tilt, the bob and the hover lift are all the button's own. Each supplies a
     fill, a lettering colour, a material at rest and one moment of weather on hover, and holds its
     end state while held. Every class is anv- (or fk-/sn- for folklore's wood and Speak Now's
     castle, and tvf-/tvr-/tvs-/tv9- for the four Taylor's Versions), and every finish id is
     anv-<album> or anv-<album>-tv, which is what the [data-startbtn^="anv-"] rules key on.
     The twelve were designed on scripts/cta/chosen-board.html, the four on tv-board.html.
     Then her birthday's, anv-birthday (bd- classes), forced the same way by birthdayFinishFor
     and designed on birthday-board.html, then the 13th of every month's, anv-13th (ch-
     classes), forced by thirteenthFinishFor and designed on thirteenth-board.html, and last
     Christmas Day's, anv-christmas (nt- classes), forced by christmasFinishFor and designed on
     christmas-board.html. */
  .btn-primary.play-cta[data-startbtn^="anv-"]::after { content:none; }
  .anv-out { position:absolute; inset:0; z-index:2; pointer-events:none; }
  .anv-out > * { position:absolute; }
  .anv-fill { inset:0; width:100%; height:100%; }

  /* ============ Taylor Swift B: Screen door ============ */
  .play-cta[data-startbtn="anv-debut"] { --cta-fill:#4f8a8d; --cta-text:#f5f3e6; --cta-hover-text:#f5f3e6; --treeline:#26504f;
    --cta-art:linear-gradient(180deg, #8bbcb8 0%, #5b9597 55%, #3f7476 100%);
