  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-firefly { animation:anvBlink var(--t) var(--d) ease-in-out 3 both, anvWander calc(var(--t) * 3) var(--d) ease-in-out both; }
