  :root[data-theme="dark"] .play-cta[data-startbtn="anv-fearless"] { --cta-fill:#5a4b2e; --cta-text:#fdf4de; --cta-hover-text:#fdf4de;
    --sqa1:#a38e61; --sqa2:#6c5a37; --sqb1:#e2bf66; --sqb2:#9a772b; --sq-edge:#4a3c22; --sq-lit:#c9b27c;
