  /* ============ Speak Now: Castle ============
     A fairy-tale castle at dusk, "fighting dragons with you" out of Long Live: a tall keep and its
     spires at the right, a gatehouse tower at the left, and a low curtain wall running between them
     under the words with a lit gate in it. Two dragons hang in the sky beside the towers and a third,
     far off, beyond them. On hover they fly: each does one lap round a tower, passing behind the
     spire and out in front of the walls, wings beating, and the one at the keep breathes fire as it
     comes past. They land back where they started, and the pennants flutter in their wake. */
  .play-cta[data-startbtn="anv-speaknow"] { --cta-fill:#b39bd0; --cta-text:#231433; --cta-hover-text:#231433;
    --keep-back:#8b6fb5; --keep:#3b2358; --dragon:#28143f; --dragon-far:#6a4f93; --lit:#ffd98a; --pennant:#e2b95a; --moon:#fbf3dc; --star:#fffaf0;
    --cta-art:linear-gradient(180deg, #8d71bc 0%, #b39bd4 55%, #d5c3e7 100%); }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-speaknow"] { --cta-fill:#3e2c58; --cta-text:#f4eefb; --cta-hover-text:#f4eefb;
    --keep-back:#4e3974; --keep:#1c1030; --dragon:#110820; --dragon-far:#6b559a; --moon:#f3e8c8;
    --cta-art:linear-gradient(180deg, #2b1d44 0%, #473465 65%, #5b4680 100%);
    background-image:linear-gradient(168deg, #ffffff14 0%, #ffffff00 46%, #0000002a 100%), var(--cta-art); }
  .sn-stars circle { fill:var(--star); }
  .sn-moon { fill:var(--moon); }
  .sn-back { fill:var(--keep-back); } .sn-front { fill:var(--keep); }
  .sn-lit { fill:var(--lit); }
  .sn-pole { fill:none; stroke:var(--keep); stroke-width:.6; }
  .sn-pennant { fill:var(--pennant); transform-box:fill-box; transform-origin:0 50%; }
  .sn-dragon { fill:var(--dragon); } .sn-dragon--far { fill:var(--dragon-far); }
  .sn-fire { fill:#ff8a3d; } .sn-fire-core { fill:#ffe28a; }

  /* The flight. The outer group flies the lap, the next one turns the dragon to face the way it is
     going, and the wings beat on their own. Every lap is the same ellipse, sized per dragon by
     --rx and --ry and run leftward or rightward by --dir, so one set of keyframes serves all three. */
  .sn-fly, .sn-face, .sn-wing { transform-origin:0 0; }
  .sn-face { transform:scaleX(var(--dir)); }
  .sn-fly--back { opacity:0; }
  .sn-flame { opacity:0; transform:scaleX(0); transform-box:fill-box; transform-origin:0 50%; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-fly { animation:snLoop var(--t) var(--d) linear both; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-fly--front { animation:snLoop var(--t) var(--d) linear both, snFront var(--t) var(--d) linear both; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-fly--back { animation:snLoop var(--t) var(--d) linear both, snBack var(--t) var(--d) linear both; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-face { animation:snTurn var(--t) var(--d) ease-in-out both; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-wing { animation:snFlap .28s var(--d) ease-in-out 12 alternate; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-wing--far { animation-delay:calc(var(--d) + .05s); }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-flame { animation:snFire var(--t) var(--d) ease-out both; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .sn-pennant { animation:snFlutter .42s calc(var(--p) + .6s) ease-in-out 6 alternate; }
  /* The first half of every lap runs along the near side, in front of the castle; the second half
     runs along the far side, behind it. Each dragon is drawn twice, once in front of the walls and
     once behind, and the two copies hand over at the ends of the lap, where no tower is in the way. */
  @keyframes snLoop {
    0%, 6% { transform:translate(0, 0); }
    11.5% { transform:translate(calc(var(--dir) * var(--rx) * -0.076), calc(var(--ry) * 0.383)); }
    17% { transform:translate(calc(var(--dir) * var(--rx) * -0.293), calc(var(--ry) * 0.707)); }
    22.5% { transform:translate(calc(var(--dir) * var(--rx) * -0.617), calc(var(--ry) * 0.924)); }
    28% { transform:translate(calc(var(--dir) * var(--rx) * -1), var(--ry)); }
    33.5% { transform:translate(calc(var(--dir) * var(--rx) * -1.383), calc(var(--ry) * 0.924)); }
    39% { transform:translate(calc(var(--dir) * var(--rx) * -1.707), calc(var(--ry) * 0.707)); }
    44.5% { transform:translate(calc(var(--dir) * var(--rx) * -1.924), calc(var(--ry) * 0.383)); }
    50%, 56% { transform:translate(calc(var(--dir) * var(--rx) * -2), 0); }
    61.5% { transform:translate(calc(var(--dir) * var(--rx) * -1.924), calc(var(--ry) * -0.383)); }
    67% { transform:translate(calc(var(--dir) * var(--rx) * -1.707), calc(var(--ry) * -0.707)); }
    72.5% { transform:translate(calc(var(--dir) * var(--rx) * -1.383), calc(var(--ry) * -0.924)); }
    78% { transform:translate(calc(var(--dir) * var(--rx) * -1), calc(var(--ry) * -1)); }
    83.5% { transform:translate(calc(var(--dir) * var(--rx) * -0.617), calc(var(--ry) * -0.924)); }
    89% { transform:translate(calc(var(--dir) * var(--rx) * -0.293), calc(var(--ry) * -0.707)); }
    94.5% { transform:translate(calc(var(--dir) * var(--rx) * -0.076), calc(var(--ry) * -0.383)); }
    100% { transform:translate(0, 0); } }
  @keyframes snFront { 0%, 52% { opacity:1; } 52.5%, 99.5% { opacity:0; } 100% { opacity:1; } }
  @keyframes snBack { 0%, 52% { opacity:0; } 52.5%, 99.5% { opacity:1; } 100% { opacity:0; } }
  @keyframes snTurn { 0% { transform:scaleX(var(--dir)); } 6%, 50% { transform:scaleX(calc(var(--dir) * -1)); } 56%, 100% { transform:scaleX(var(--dir)); } }
  @keyframes snFlap { from { transform:scaleY(1); } to { transform:scaleY(-.45); } }
  @keyframes snFire { 0%, 24% { opacity:0; transform:scaleX(0); } 28% { opacity:1; transform:scaleX(.55); } 34%, 40% { opacity:1; transform:scaleX(1); } 46%, 100% { opacity:0; transform:scaleX(1.15); } }
  @keyframes snFlutter { from { transform:none; } to { transform:scaleX(.72) skewY(9deg); } }

  /* ============ Red: Scarf ============ */
  .play-cta[data-startbtn="anv-red"] { --cta-fill:#ad2f2d; --cta-text:#fdf0e4; --cta-hover-text:#fdf0e4;
