  @keyframes anvGust { 0%, 100% { transform:rotate(var(--rot)); } 28% { transform:rotate(calc(var(--rot) + 16deg)); }
    56% { transform:rotate(calc(var(--rot) - 8deg)); } 80% { transform:rotate(calc(var(--rot) + 3deg)); } }

  /* ============ 1989: Skyline ============ */
  .play-cta[data-startbtn="anv-1989"] { --cta-fill:#a7cde5; --cta-text:#14304a; --cta-hover-fill:#a7cde5; --cta-hover-text:#fff4e4;
    --bld-back:#86b2d1; --bld:#5a8cb3; --bld-back-dusk:#3b4f7b; --bld-dusk:#23345a; --gull:#2c4c66; --window:#ffd98a;
