    --bld-back:#2b4868; --bld:#1d334f; --bld-back-dusk:#2a3558; --bld-dusk:#141f38; --gull:#c9d6e2;
    --cta-art:linear-gradient(180deg, #213857 0%, #33547a 80%, #3d5f84 100%);
    --dusk:linear-gradient(180deg, #1b2747 0%, #3b4577 52%, #86607a 100%);
