  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-windows rect { opacity:1; transition:opacity .25s var(--d); }
  .anv-gull { fill:none; stroke:var(--gull); stroke-width:.9; stroke-linecap:round; stroke-linejoin:round; transition:transform .6s, opacity .4s; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-gull { transform:translate(38px, -16px); opacity:0; transition:transform 1.6s cubic-bezier(.4,.1,.6,1) var(--gd), opacity .6s 1s; }

  /* ============ reputation: Emerald scales ============
     Snakeskin laid the way the Fearless sequins are: the whole face covered edge to edge in one
     offset grid, every scale shaded on its own and a few catching more light or less. Each row
     lies over the one below it, so what shows of a scale is its rounded lower edge. On hover an
     emerald front runs through them from left to right, bent into a slow S, and every scale it
     crosses flashes pale at the edge and settles deep green. */
  .play-cta[data-startbtn="anv-rep"] { --cta-fill:#232327; --cta-text:#ecebe6; --cta-hover-text:#ecebe6;
    --rs1:#55555e; --rs2:#1d1d22; --rs-lit:#8a8a95; --rs-dark:#0f0f12; --rs-edge:#08080a;
    --em1:#2e9e6d; --em2:#0b4a30; --em-lit:#7fdcae; --em-dark:#052a1b; --em-edge:#02130c; --em-flash:#e4fff1;
    background-image:none; }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-rep"] { --cta-fill:#2c2c31; --cta-text:#f2f1ec; --cta-hover-text:#f2f1ec;
    --rs1:#5f5f69; --rs2:#26262c; --rs-lit:#90909b; --rs-dark:#16161a; }
