  .anv-rs1 { stop-color:var(--rs1); } .anv-rs2 { stop-color:var(--rs2); } .anv-rs-lit { stop-color:var(--rs-lit); } .anv-rs-dark { stop-color:var(--rs-dark); }
  .anv-em1 { stop-color:var(--em1); } .anv-em2 { stop-color:var(--em2); } .anv-em-lit { stop-color:var(--em-lit); } .anv-em-dark { stop-color:var(--em-dark); }
  .anv-rs-em { opacity:0; transition:opacity .35s ease calc(var(--d) * .4); }
  .anv-rs-edge { fill:none; stroke:var(--rs-edge); stroke-width:.55; stroke-opacity:.8; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-rs-em { opacity:1; transition:opacity .5s ease var(--d); }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-rs-edge { animation:anvRsEdge .85s var(--d) ease-out both; }
  @keyframes anvRsEdge { 0% { stroke:var(--rs-edge); stroke-opacity:.8; } 22% { stroke:var(--em-flash); stroke-opacity:1; stroke-width:.8; } 100% { stroke:var(--em-edge); stroke-opacity:.9; } }

  /* ============ Lover: Butterflies ============ */
  .play-cta[data-startbtn="anv-lover"] { --cta-fill:#eeaccb; --cta-text:#3e1431; --cta-hover-text:#3e1431; --wing-edge:#3a2331;
    --cta-art:radial-gradient(ellipse 24% 120% at 0% 62%, #b7d3f4c0, #b7d3f400 100%), radial-gradient(ellipse 24% 120% at 100% 38%, #d5c0f3c0, #d5c0f300 100%); }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-lover"] { --cta-fill:#8c4a6a; --cta-text:#fcecf4; --cta-hover-text:#fcecf4; --wing-edge:#2a1420;
    --cta-art:radial-gradient(ellipse 24% 120% at 0% 62%, #5f7fb080, #5f7fb000 100%), radial-gradient(ellipse 24% 120% at 100% 38%, #8a70b880, #8a70b800 100%);
    background-image:linear-gradient(168deg, #ffffff18 0%, #ffffff00 46%, #0000002a 100%), var(--cta-art); }
  .anv-bfly { width:20px; height:18px; transform:rotate(var(--rot)); animation:anvLand .5s ease-out both; }
  .anv-bfly svg { display:block; width:100%; height:100%; overflow:visible; }
  .anv-wing path { fill:var(--c); stroke:var(--wing-edge); stroke-width:.55; stroke-linejoin:round; }
  .anv-spot { fill:var(--wing-edge); opacity:.55; }
  .anv-body { fill:var(--wing-edge); }
  .anv-feeler { fill:none; stroke:var(--wing-edge); stroke-width:.45; stroke-linecap:round; }
  .anv-wing { transform-box:fill-box; transform:scaleX(.8); }
  .anv-wing--l { transform-origin:100% 50%; } .anv-wing--r { transform-origin:0 50%; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-bfly { animation:anvFly 2.1s var(--d) cubic-bezier(.45,0,.55,1) forwards; }
  .play-cta[data-startbtn^="anv-"]:is(:hover, :focus-visible) .anv-wing { animation:anvFlap .13s var(--d) ease-in-out 16 alternate; }
  @keyframes anvLand { 0% { opacity:0; transform:translateY(-5px) rotate(var(--rot)); } 100% { opacity:1; transform:rotate(var(--rot)); } }
  @keyframes anvFlap { from { transform:scaleX(.85); } to { transform:scaleX(.14); } }
  @keyframes anvFly { 0% { transform:rotate(var(--rot)); }
    22% { transform:translate(calc(var(--fx) * .12), -9px) rotate(calc(var(--rot) * .4)); }
    48% { transform:translate(calc(var(--fx) * .5), calc(var(--fy) * .42)) rotate(calc(var(--rot) * -1)); }
    76% { opacity:1; transform:translate(calc(var(--fx) * .78), calc(var(--fy) * .8)) rotate(var(--rot)); }
    100% { opacity:0; transform:translate(var(--fx), var(--fy)) rotate(0); } }

  /* ============ folklore: Tall timber, step inside ============
     The woods from inside: straight trunks rising out of the top of the frame with no canopy in
     sight, bracken at the feet of the near ones and wisps of fog hanging between. On hover the
     camera walks in: scaling each depth from one point on the ground is exactly how a wood moves
     when you walk into it, so the near trunks part and slide past and the far ones barely move. */
  .play-cta[data-startbtn="anv-folklore"] {
    --cta-fill:#d8d6d0; --cta-text:#22211e; --cta-hover-text:#22211e;
    --t-back:#c3c1bb; --t-mid:#9a9891; --t-front:#46443f; --bark:#8d8a82;
    --fog:#ebe9e3; --fog-0:#ebe9e300;
    --cta-art:linear-gradient(180deg, #cac8c2 0%, #d8d6d0 50%, #e2e0da 100%); }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-folklore"] {
    --cta-fill:#403f3b; --cta-text:#f1eee6; --cta-hover-text:#f1eee6;
    --t-back:#373633; --t-mid:#2b2a27; --t-front:#161514; --bark:#3a3835;
    --fog:#5d5b56; --fog-0:#5d5b5600;
    --cta-art:linear-gradient(180deg, #373633 0%, #403f3b 55%, #4a4844 100%);
    background-image:linear-gradient(168deg, #ffffff12 0%, #ffffff00 46%, #0000002a 100%), var(--cta-art); }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-folklore"] .cta-label { text-shadow:0 1px 3px #1a1918; }
  .fk-back { fill:var(--t-back); } .fk-mid { fill:var(--t-mid); } .fk-front { fill:var(--t-front); }
  .fk-bark { fill:none; stroke:var(--bark); stroke-width:.55; stroke-linecap:round; opacity:.55; }
