    background-image:linear-gradient(168deg, #ffffff50 0%, #ffffff00 46%, #6b3a2016 100%), var(--cta-art); }
  :root[data-theme="dark"] .play-cta[data-startbtn="anv-birthday"] { --cta-fill:#e2d2bb; --cta-text:#8e2649; --cta-hover-text:#8e2649;
    --bd-shell:#dc9aab; --bd-ridge:#b8718a; --bd-hi:#f4d7e0; --bd-knife:#cdb698; --bd-script:#982c50; --bd-script-edge:#6e1a37;
    --cta-art:radial-gradient(ellipse 60% 120% at 30% 0%, #ece0cc 0%, #ece0cc00 70%), linear-gradient(180deg, #e6d8c2 0%, #d6c3a8 100%);
    background-image:linear-gradient(168deg, #ffffff20 0%, #ffffff00 46%, #0000002a 100%), var(--cta-art); }
