    --btn-mark: rgba(122, 90, 158, 0.42);
    background-color: var(--btn-wash);
    background-image: radial-gradient(circle, transparent 1.4px, var(--btn-mark) 1.5px 2.3px, transparent 2.4px);
    background-size: 11px 11px;
